INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C1','math',4,1,'u1',2,'10000 알아보기 — 1000이 10개인 수를 10000(만)이라 쓰고 읽으며, 9999보다 1·9990보다 10·9900보다 100·9000보다 1000 큰 수이자 100의 100배임을 알고 돈으로 만들기',ARRAY['4수01-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C2','math',4,1,'u1',3,'다섯 자리 수 쓰고 읽기 — 10000·1000·100·10·1의 개수로 수를 쓰고, 0인 자리는 빼고 읽으며 읽은 말을 수로 쓸 때는 빈 자리에 0 채우기',ARRAY['4수01-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C3','math',4,1,'u1',3,'다섯 자리 수의 자릿값 — 만·천·백·십·일의 자리 숫자와 그 숫자가 나타내는 값을 구별하고, 수를 각 자리 값의 합으로 나타내기',ARRAY['4수01-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C4','math',4,1,'u1',4,'십만·백만·천만 — 10000이 10개·100개·1000개인 수를 알고, 천만의 자리까지 자리 숫자와 나타내는 값을 구하기',ARRAY['4수01-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C5','math',4,1,'u1',4,'천만 단위 수 읽고 쓰기 — 일의 자리부터 네 자리씩 끊어 「만」과 「일」 단위로 읽고, 「몇천몇백만 몇천…」을 수로 쓰기',ARRAY['4수01-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C6','math',4,1,'u1',5,'억 알아보기 — 1000만이 10개인 수를 1억이라 하고, 억 단위 수를 네 자리씩 끊어 읽고 쓰며 「억이 몇 개인 수」 알기',ARRAY['4수01-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C7','math',4,1,'u1',5,'조 알아보기 — 1000억이 10개인 수를 1조라 하고, 조·억·만·일로 네 자리씩 끊어 조 단위 수를 읽고 쓰며 자리 숫자 찾기',ARRAY['4수01-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C8','math',4,1,'u1',6,'큰 수 뛰어 세기 — 10000씩·10만씩·1억씩 등 일정하게 뛰어 세며 바뀌는 자리를 찾고, 자리가 넘어갈 때 윗자리로 올리며 거꾸로도 뛰어 세기',ARRAY['4수01-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C9','math',4,1,'u1',7,'큰 수의 크기 비교 — 자릿수가 다르면 자릿수가 많은 수가 크고, 같으면 가장 높은 자리부터 차례로 비교해 > · <로 나타내기',ARRAY['4수01-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u1-C10','math',4,1,'u1',7,'조건에 맞는 큰 수 만들기 — 수 카드로 가장 큰·작은 수를 만들고(0은 맨 앞에 못 옴), □ 안에 들어갈 수 있는 숫자 찾기',ARRAY['4수01-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X01','math',4,'u1',ARRAY['M4-1-u1-C2','M4-1-u1-C5','M4-1-u1-C6','M4-1-u1-C7']::text[],'0인 자리를 빼고 수를 쓴다(육만 구천사백십 → 6941, 백사십삼만 오십 → 14350)','빈 자리에 0 채우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X02','math',4,'u1',ARRAY['M4-1-u1-C3','M4-1-u1-C4']::text[],'숫자와 그 숫자가 나타내는 값을 같게 본다(68263에서 만의 자리 6이 나타내는 값을 6으로)','숫자 × 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X03','math',4,'u1',ARRAY['M4-1-u1-C1','M4-1-u1-C3','M4-1-u1-C4']::text[],'0을 하나 덜 쓰거나 더 써서 값이 한 자리 어긋난다(만의 자리 6 → 6000·600000)','자리 이름만큼 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X04','math',4,'u1',ARRAY['M4-1-u1-C5','M4-1-u1-C6','M4-1-u1-C7']::text[],'일의 자리가 아니라 앞에서부터 네 자리씩 끊어 단위를 붙인다(325700000 → 삼천이백오십칠억)','끊기는 일의 자리부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X05','math',4,'u1',ARRAY['M4-1-u1-C5','M4-1-u1-C6','M4-1-u1-C7']::text[],'만·억·조 단위를 서로 바꾼다(325700000000을 삼천이백오십칠만으로)','네 자리마다 만→억→조') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X06','math',4,'u1',ARRAY['M4-1-u1-C2','M4-1-u1-C5']::text[],'0인 자리까지 「영」을 넣어 읽는다(19604 → 만 구천육백영사)','0인 자리는 건너뛰고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X07','math',4,'u1',ARRAY['M4-1-u1-C1','M4-1-u1-C4','M4-1-u1-C6','M4-1-u1-C7']::text[],'「몇 개인 수」의 관계를 헷갈린다 — 10배와 100배(10000은 100이 10개, 1억은 100만이 10개)','10개씩 모이면 윗자리 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X08','math',4,'u1',ARRAY['M4-1-u1-C8']::text[],'뛰어 셀 때 다른 자리 숫자를 바꾼다(10만씩 뛰어 세는데 만의 자리를 1씩 키움)','뛰는 수의 자리만 바뀜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X09','math',4,'u1',ARRAY['M4-1-u1-C8']::text[],'자리가 넘어갈 때 윗자리로 올리지 않는다(9800만에서 1000만 뛰어 1억 800만을 800만으로)','10이 되면 윗자리로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X10','math',4,'u1',ARRAY['M4-1-u1-C8']::text[],'거꾸로 뛰어 세기의 방향을 바꾸어 커지게 센다','거꾸로는 작아지게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X11','math',4,'u1',ARRAY['M4-1-u1-C9']::text[],'자릿수가 다른데 맨 앞 숫자만 견준다(99999가 100000보다 크다)','먼저 자릿수 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X12','math',4,'u1',ARRAY['M4-1-u1-C9']::text[],'자릿수가 같은데 낮은 자리부터 견주거나 뒤쪽 숫자에 속는다(6712000이 6721000보다 크다)','높은 자리부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X13','math',4,'u1',ARRAY['M4-1-u1-C9']::text[],'부등호(>·<)의 방향을 거꾸로 쓴다','벌어진 쪽이 큰 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X14','math',4,'u1',ARRAY['M4-1-u1-C10']::text[],'수 카드로 수를 만들 때 큰 숫자부터 놓지 않거나 0을 맨 앞에 놓는다','높은 자리부터 큰 숫자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X15','math',4,'u1',ARRAY['M4-1-u1-C1','M4-1-u1-C2','M4-1-u1-C3','M4-1-u1-C4','M4-1-u1-C5','M4-1-u1-C6','M4-1-u1-C7','M4-1-u1-C8','M4-1-u1-C9','M4-1-u1-C10']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 큰↔작은, 아닌↔맞는','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X16','math',4,'u1',ARRAY['M4-1-u1-C1','M4-1-u1-C2','M4-1-u1-C4','M4-1-u1-C5','M4-1-u1-C6','M4-1-u1-C7']::text[],'자릿수(0의 개수)를 잘못 세어 숫자를 빠뜨리거나 0을 하나 더 쓴다','네 자리씩 점 찍고 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u1-X18','math',4,'u1',ARRAY['M4-1-u1-C1','M4-1-u1-C2','M4-1-u1-C3','M4-1-u1-C4','M4-1-u1-C5','M4-1-u1-C6','M4-1-u1-C7','M4-1-u1-C8','M4-1-u1-C9','M4-1-u1-C10']::text[],'수를 옮겨 쓰거나 읽을 때 숫자 순서를 바꾸거나 다른 숫자로 쓴다','한 자리씩 짚으며 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#1','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',1,'mc','auto','1000이 10개인 수는 얼마인가요?',ARRAY['M4-1-u1-X07','M4-1-u1-X16']::text[],true,'{"seq":1,"concept":"M4-1-u1-C1","difficulty":1,"kind":"mc","stem":"1000이 10개인 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"1000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"100","mis":"M4-1-u1-X16"}],"explanation":["1000이 10개인 수는 1000 × 10으로 구해요.","1000 × 10 = 10000 — 0을 4개 써요.","수로 쓰면 10000, 「만」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"100이 100개인 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"1000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"100","mis":"M4-1-u1-X16"}],"explanation":["100이 100개인 수는 100 × 100으로 구해요.","100 × 100 = 10000 — 0을 4개 써요.","수로 쓰면 10000, 「만」이라고 읽어요."],"asset":null},{"stem":"10이 1000개인 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"1000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"100","mis":"M4-1-u1-X16"}],"explanation":["10이 1000개인 수는 10 × 1000으로 구해요.","10 × 1000 = 10000 — 0을 4개 써요.","수로 쓰면 10000, 「만」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#2','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',1,'sa','auto','10000은 9999보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u1-C1","difficulty":1,"kind":"sa","stem":"10000은 9999보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["9999에서 10000까지 몇이 남았는지 세어요.","9999 + 1 = 10000이에요.","10000은 9999보다 1 더 큰 수예요."],"variant_rule":{"alt":[{"stem":"10000은 9990보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["9990에서 10000까지 몇이 남았는지 세어요.","9990 + 10 = 10000이에요.","10000은 9990보다 10 더 큰 수예요."],"asset":null},{"stem":"10000은 9900보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["9900에서 10000까지 몇이 남았는지 세어요.","9900 + 100 = 10000이에요.","10000은 9900보다 100 더 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#3','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',1,'sa','auto','1000원짜리 지폐만 모아 10000원을 만들려고 해요. 1000원짜리 지폐가 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u1-C1","difficulty":1,"kind":"sa","stem":"1000원짜리 지폐만 모아 10000원을 만들려고 해요. 1000원짜리 지폐가 몇 장 필요한가요? 숫자로 쓰세요.","answer":["10"],"explanation":["10000원은 1000원이 몇 장인지 생각해요.","1000원 × 10 = 10000원.","1000원짜리 지폐 10장이 필요해요."],"variant_rule":{"alt":[{"stem":"100원짜리 동전만 모아 10000원을 만들려고 해요. 100원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["100"],"explanation":["10000원은 100원이 몇 개인지 생각해요.","100원 × 100 = 10000원.","100원짜리 동전 100개가 필요해요."],"asset":null},{"stem":"10원짜리 동전만 모아 10000원을 만들려고 해요. 10원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["10000원은 10원이 몇 개인지 생각해요.","10원 × 1000 = 10000원.","10원짜리 동전 1000개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#4','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',1,'sa','auto','10000은 7000보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u1-C1","difficulty":1,"kind":"sa","stem":"10000은 7000보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["7000에서 10000까지 몇이 남았는지 세어요.","7000 + 3000 = 10000이에요.","10000은 7000보다 3000 더 큰 수예요."],"variant_rule":{"alt":[{"stem":"10000은 6000보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["4000"],"explanation":["6000에서 10000까지 몇이 남았는지 세어요.","6000 + 4000 = 10000이에요.","10000은 6000보다 4000 더 큰 수예요."],"asset":null},{"stem":"10000은 8000보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["2000"],"explanation":["8000에서 10000까지 몇이 남았는지 세어요.","8000 + 2000 = 10000이에요.","10000은 8000보다 2000 더 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#5','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',2,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X10']::text[],true,'{"seq":5,"concept":"M4-1-u1-C1","difficulty":2,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"100000","mis":"M4-1-u1-X16"},{"t":"1000","mis":"M4-1-u1-X16"},{"t":"9996","mis":"M4-1-u1-X10"}],"explanation":["1씩 커지므로 빈칸은 9999보다 1 큰 수예요.","9999 + 1 = 10000 — 9 다음 10이 되어 윗자리로 올라가요.","빈칸은 10000(만)이에요."],"asset":{"type":"number_line","cells":["9997","9998","9999",null]},"variant_rule":{"alt":[{"stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"100000","mis":"M4-1-u1-X16"},{"t":"1000","mis":"M4-1-u1-X16"},{"t":"9960","mis":"M4-1-u1-X10"}],"explanation":["10씩 커지므로 빈칸은 9990보다 10 큰 수예요.","9990 + 10 = 10000 — 9 다음 10이 되어 윗자리로 올라가요.","빈칸은 10000(만)이에요."],"asset":{"type":"number_line","cells":["9970","9980","9990",null]}},{"stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"100000","mis":"M4-1-u1-X16"},{"t":"1000","mis":"M4-1-u1-X16"},{"t":"9600","mis":"M4-1-u1-X10"}],"explanation":["100씩 커지므로 빈칸은 9900보다 100 큰 수예요.","9900 + 100 = 10000 — 9 다음 10이 되어 윗자리로 올라가요.","빈칸은 10000(만)이에요."],"asset":{"type":"number_line","cells":["9700","9800","9900",null]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#6','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',2,'mc','auto','10000을 바르게 설명한 것은 어느 것인가요?',ARRAY['M4-1-u1-X07','M4-1-u1-X03']::text[],true,'{"seq":6,"concept":"M4-1-u1-C1","difficulty":2,"kind":"mc","stem":"10000을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"9990보다 10 큰 수","correct":true},{"t":"1000이 100개인 수","mis":"M4-1-u1-X07"},{"t":"100이 10개인 수","mis":"M4-1-u1-X07"},{"t":"9000보다 100 큰 수","mis":"M4-1-u1-X03"}],"explanation":["9990 + 10 = 10000 — 그래서 10000이에요.","나머지: 1000이 100개면 100000, 100이 10개면 1000.","10000은 1000이 10개, 100이 100개, 9999보다 1 큰 수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 10000을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"100이 100개인 수","correct":true},{"t":"9990보다 1 큰 수","mis":"M4-1-u1-X03"},{"t":"1000이 100개인 수","mis":"M4-1-u1-X07"},{"t":"100이 10개인 수","mis":"M4-1-u1-X07"}],"explanation":["100 × 100 = 10000 — 그래서 10000이에요.","나머지: 9990보다 1 크면 9991, 1000이 100개면 100000.","10000은 1000이 10개, 100이 100개, 9999보다 1 큰 수예요."],"asset":null},{"stem":"이번에는 다른 수예요. 10000을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"9000보다 1000 큰 수","correct":true},{"t":"9900보다 10 큰 수","mis":"M4-1-u1-X03"},{"t":"100이 10개인 수","mis":"M4-1-u1-X07"},{"t":"10이 100개인 수","mis":"M4-1-u1-X07"}],"explanation":["9000 + 1000 = 10000 — 그래서 10000이에요.","나머지: 9900보다 10 크면 9910, 100이 10개면 1000.","10000은 1000이 10개, 100이 100개, 9999보다 1 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#7','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',2,'sa','auto','500원짜리 동전만 모아 10000원을 만들려고 해요. 500원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u1-C1","difficulty":2,"kind":"sa","stem":"500원짜리 동전만 모아 10000원을 만들려고 해요. 500원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["20"],"explanation":["10000원은 500원이 몇 개인지 생각해요.","500원 × 20 = 10000원.","500원짜리 동전 20개가 필요해요."],"variant_rule":{"alt":[{"stem":"5000원짜리 지폐만 모아 10000원을 만들려고 해요. 5000원짜리 지폐가 몇 장 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10000원은 5000원이 몇 장인지 생각해요.","5000원 × 2 = 10000원.","5000원짜리 지폐 2장이 필요해요."],"asset":null},{"stem":"50원짜리 동전만 모아 10000원을 만들려고 해요. 50원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["200"],"explanation":["10000원은 50원이 몇 개인지 생각해요.","50원 × 200 = 10000원.","50원짜리 동전 200개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#8','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',2,'ox','auto','10000은 100이 10개인 수예요.',ARRAY['M4-1-u1-X07']::text[],true,'{"seq":8,"concept":"M4-1-u1-C1","difficulty":2,"kind":"ox","stem":"10000은 100이 10개인 수예요.","answer":"X","reason_options":[{"t":"100이 100개여야 10000이라서","correct":true},{"t":"100이 10개 모이면 10000이라서","mis":"M4-1-u1-X07"}],"mis":"M4-1-u1-X07","explanation":["100이 10개면 1000이에요.","10000은 100이 100개인 수예요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"10000은 1000이 10개인 수예요.","answer":"O","reason_options":[{"t":"1000이 10개 모이면 10000이라서","correct":true},{"t":"1000이 100개여야 10000이라서","mis":"M4-1-u1-X07"}],"explanation":["1000 × 10 = 10000이에요.","10000은 1000이 10개인 수예요.","그래서 맞아요."],"asset":null},{"stem":"9000보다 100 큰 수는 10000이에요.","answer":"X","reason_options":[{"t":"9000보다 100 크면 9100이라서","correct":true},{"t":"9000 다음 자리는 바로 10000이라서","mis":"M4-1-u1-X03"}],"explanation":["9000 + 100 = 9100이에요.","10000은 9000보다 1000 큰 수예요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#9','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',2,'sa','auto','지유는 학용품을 사려고 1000원짜리 지폐 7장을 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u1-C1","difficulty":2,"kind":"sa","stem":"지유는 학용품을 사려고 1000원짜리 지폐 7장을 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["3000"],"explanation":["1000원짜리 지폐 7장은 7000원이에요.","10000 − 7000 = 3000.","3000원이 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"지유는 학용품을 사려고 1000원짜리 지폐 6장, 100원짜리 동전 20개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["2000"],"explanation":["가진 돈: 6000원 + 2000원 = 8000원.","10000 − 8000 = 2000.","2000원이 더 있어야 해요."],"asset":null},{"stem":"지유는 학용품을 사려고 1000원짜리 지폐 8장, 100원짜리 동전 5개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["1500"],"explanation":["가진 돈: 8000원 + 500원 = 8500원.","10000 − 8500 = 1500.","1500원이 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_basic#10','math',4,1,'u1','L02','g4_1_math_u1_L02_basic','lesson_basic','M4-1-u1-C1',3,'error','auto','10000에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u1-X07','M4-1-u1-X15']::text[],true,'{"seq":10,"concept":"M4-1-u1-C1","difficulty":3,"kind":"error","stem":"10000에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「10000은 1000이 100개인 수예요」","correct":true,"mis_target":"M4-1-u1-X07"},{"t":"시아 — 「10000은 9999보다 1 큰 수예요」","mis":"M4-1-u1-X15"},{"t":"지유 — 「10000은 9900보다 100 큰 수예요」","mis":"M4-1-u1-X15"}],"explanation":["1000이 100개면 100000 — 10000이 아니에요.","9999 + 1 = 10000, 9900 + 100 = 10000.","하린이 잘못 말했어요 — 10개씩 모이면 윗자리 하나."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 10000에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「10000은 9000보다 100 큰 수예요」","correct":true,"mis_target":"M4-1-u1-X03"},{"t":"하린 — 「10000은 9900보다 100 큰 수예요」","mis":"M4-1-u1-X15"},{"t":"도윤 — 「10000은 100이 100개인 수예요」","mis":"M4-1-u1-X15"}],"explanation":["9000보다 100 크면 9100 — 10000이 아니에요.","9900 + 100 = 10000, 100 × 100 = 10000.","은우가 잘못 말했어요 — 자리 이름만큼 0."],"asset":null},{"stem":"이번에는 다른 수예요. 10000에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「10000은 9900보다 10 큰 수예요」","correct":true,"mis_target":"M4-1-u1-X03"},{"t":"은우 — 「10000은 9990보다 10 큰 수예요」","mis":"M4-1-u1-X15"},{"t":"태오 — 「10000은 10이 1000개인 수예요」","mis":"M4-1-u1-X15"}],"explanation":["9900보다 10 크면 9910 — 10000이 아니에요.","9990 + 10 = 10000, 10 × 1000 = 10000.","서준이 잘못 말했어요 — 자리 이름만큼 0."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#1','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',2,'match','auto','설명과 수를 알맞게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u1-C1","difficulty":2,"kind":"match","stem":"설명과 수를 알맞게 이으세요.","pairs":[{"l":"1000이 10개인 수","r":"10000"},{"l":"100이 10개인 수","r":"1000"},{"l":"10이 10개인 수","r":"100"}],"mis":"M4-1-u1-X07","explanation":["10개가 모이면 윗자리 하나가 돼요.","1000이 10개인 수 → 10000, 100이 10개인 수 → 1000, 10이 10개인 수 → 100.","10000은 만이라고 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 설명과 수를 알맞게 이으세요.","pairs":[{"l":"9000보다 1000 큰 수","r":"10000"},{"l":"900보다 100 큰 수","r":"1000"},{"l":"90보다 10 큰 수","r":"100"}],"explanation":["10개가 모이면 윗자리 하나가 돼요.","9000보다 1000 큰 수 → 10000, 900보다 100 큰 수 → 1000, 90보다 10 큰 수 → 100.","10000은 만이라고 읽어요."],"asset":null},{"stem":"이번에는 다른 수예요. 설명과 수를 알맞게 이으세요.","pairs":[{"l":"9999보다 1 큰 수","r":"10000"},{"l":"999보다 1 큰 수","r":"1000"},{"l":"99보다 1 큰 수","r":"100"}],"explanation":["10개가 모이면 윗자리 하나가 돼요.","9999보다 1 큰 수 → 10000, 999보다 1 큰 수 → 1000, 99보다 1 큰 수 → 100.","10000은 만이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#2','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',2,'sa','auto','10000은 100의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u1-C1","difficulty":2,"kind":"sa","stem":"10000은 100의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["100이 100개 모이면 10000이에요.","100 × 100 = 10000.","100배예요."],"variant_rule":{"alt":[{"stem":"10000은 1000의 몇 배인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["1000이 10개 모이면 10000이에요.","1000 × 10 = 10000.","10배예요."],"asset":null},{"stem":"10000은 10의 몇 배인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["10이 1000개 모이면 10000이에요.","10 × 1000 = 10000.","1000배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#3','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',3,'sa','auto','지유는 학용품을 사려고 1000원짜리 지폐 8장, 100원짜리 동전 15개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u1-C1","difficulty":3,"kind":"sa","stem":"지유는 학용품을 사려고 1000원짜리 지폐 8장, 100원짜리 동전 15개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["500"],"explanation":["가진 돈: 8000원 + 1500원 = 9500원.","10000 − 9500 = 500.","500원이 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"지유는 학용품을 사려고 1000원짜리 지폐 5장, 500원짜리 동전 6개, 100원짜리 동전 9개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["1100"],"explanation":["가진 돈: 5000원 + 3000원 + 900원 = 8900원.","10000 − 8900 = 1100.","1100원이 더 있어야 해요."],"asset":null},{"stem":"지유는 학용품을 사려고 5000원짜리 지폐 1장, 1000원짜리 지폐 3장, 100원짜리 동전 12개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["800"],"explanation":["가진 돈: 5000원 + 3000원 + 1200원 = 9200원.","10000 − 9200 = 800.","800원이 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#4','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',3,'sa','auto','10000원짜리 지폐 1장을 1000원짜리 지폐 6장과 100원짜리 동전 몇 개로 바꾸려고 해요. 100원짜리 동전은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u1-C1","difficulty":3,"kind":"sa","stem":"10000원짜리 지폐 1장을 1000원짜리 지폐 6장과 100원짜리 동전 몇 개로 바꾸려고 해요. 100원짜리 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["1000원짜리 6장은 6000원.","10000 − 6000 = 4000원이 남아요.","4000원 = 100원 × 40 — 40개예요."],"variant_rule":{"alt":[{"stem":"10000원짜리 지폐 1장을 1000원짜리 지폐 7장과 500원짜리 동전 몇 개로 바꾸려고 해요. 500원짜리 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1000원짜리 7장은 7000원.","10000 − 7000 = 3000원이 남아요.","3000원 = 500원 × 6 — 6개예요."],"asset":null},{"stem":"10000원짜리 지폐 1장을 1000원짜리 지폐 4장과 100원짜리 동전 몇 개로 바꾸려고 해요. 100원짜리 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["1000원짜리 4장은 4000원.","10000 − 4000 = 6000원이 남아요.","6000원 = 100원 × 60 — 60개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#5','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',3,'sa','auto','어떤 수보다 1000 큰 수가 10000이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u1-C1","difficulty":3,"kind":"sa","stem":"어떤 수보다 1000 큰 수가 10000이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["9000"],"explanation":["어떤 수 + 1000 = 10000.","10000 − 1000 = 9000.","어떤 수는 9000이에요."],"variant_rule":{"alt":[{"stem":"어떤 수보다 100 큰 수가 10000이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["9900"],"explanation":["어떤 수 + 100 = 10000.","10000 − 100 = 9900.","어떤 수는 9900이에요."],"asset":null},{"stem":"어떤 수보다 10 큰 수가 10000이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["9990"],"explanation":["어떤 수 + 10 = 10000.","10000 − 10 = 9990.","어떤 수는 9990이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#6','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',3,'mc','auto','10000을 잘못 설명한 것은 어느 것인가요?',ARRAY['M4-1-u1-X15']::text[],true,'{"seq":6,"concept":"M4-1-u1-C1","difficulty":3,"kind":"mc","stem":"10000을 잘못 설명한 것은 어느 것인가요?","options":[{"t":"100이 10개인 수","correct":true},{"t":"1000이 10개인 수","mis":"M4-1-u1-X15"},{"t":"9999보다 1 큰 수","mis":"M4-1-u1-X15"},{"t":"10이 1000개인 수","mis":"M4-1-u1-X15"}],"explanation":["100이 10개면 1000 — 10000이 아니에요.","나머지는 모두 10000이에요: 1000 × 10 = 10000, 9999 + 1 = 10000.","틀린 것은 「100이 10개인 수」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 10000을 잘못 설명한 것은 어느 것인가요?","options":[{"t":"9000보다 100 큰 수","correct":true},{"t":"100이 100개인 수","mis":"M4-1-u1-X15"},{"t":"9900보다 100 큰 수","mis":"M4-1-u1-X15"},{"t":"1000이 10개인 수","mis":"M4-1-u1-X15"}],"explanation":["9000보다 100 크면 9100 — 10000이 아니에요.","나머지는 모두 10000이에요: 100 × 100 = 10000, 9900 + 100 = 10000.","틀린 것은 「9000보다 100 큰 수」예요."],"asset":null},{"stem":"이번에는 다른 수예요. 10000을 잘못 설명한 것은 어느 것인가요?","options":[{"t":"9999보다 10 큰 수","correct":true},{"t":"9000보다 1000 큰 수","mis":"M4-1-u1-X15"},{"t":"9990보다 10 큰 수","mis":"M4-1-u1-X15"},{"t":"100이 100개인 수","mis":"M4-1-u1-X15"}],"explanation":["9999보다 10 크면 10009 — 10000이 아니에요.","나머지는 모두 10000이에요: 9000 + 1000 = 10000, 9990 + 10 = 10000.","틀린 것은 「9999보다 10 큰 수」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#7','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',3,'ox','auto','9999보다 1 큰 수와 9990보다 10 큰 수는 같은 수예요.',ARRAY['M4-1-u1-X15']::text[],true,'{"seq":7,"concept":"M4-1-u1-C1","difficulty":3,"kind":"ox","stem":"9999보다 1 큰 수와 9990보다 10 큰 수는 같은 수예요.","answer":"O","reason_options":[{"t":"둘 다 10000이라서","correct":true},{"t":"더하는 수가 달라서 다른 수라서","mis":"M4-1-u1-X15"}],"mis":"M4-1-u1-X15","explanation":["9999 + 1 = 10000, 9990 + 10 = 10000.","두 수가 같아요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"9900보다 10 큰 수는 10000이에요.","answer":"X","reason_options":[{"t":"9900보다 10 크면 9910이라서","correct":true},{"t":"9900 다음은 바로 10000이라서","mis":"M4-1-u1-X03"}],"explanation":["9900 + 10 = 9910이에요.","10000은 9900보다 100 큰 수예요.","그래서 틀렸어요."],"asset":null},{"stem":"10000은 10이 1000개인 수예요.","answer":"O","reason_options":[{"t":"10 × 1000 = 10000이라서","correct":true},{"t":"10이 100개여야 10000이라서","mis":"M4-1-u1-X07"}],"explanation":["10이 100개면 1000이에요.","10이 1000개면 10000이에요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#8','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',4,'essay','teacher','지유는 1000원짜리 지폐 10장을 모았어요. 지유가 모은 돈이 얼마인지 쓰고, 그 수를 세 가지 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u1-C1","difficulty":4,"kind":"essay","stem":"지유는 1000원짜리 지폐 10장을 모았어요. 지유가 모은 돈이 얼마인지 쓰고, 그 수를 세 가지 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 10000원(만 원)이다. ① 1000이 10개인 수 ② 9000보다 1000 큰 수 ③ 100이 100개인 수(또는 9999보다 1 큰 수).","scoring_points":["10000원이라고 답했는가","1000이 10개인 수라고 설명했는가","다른 방법(○보다 □ 큰 수·100이 100개)을 두 가지 더 썼는가"]},"explanation":["1000 × 10 = 10000.","9000 + 1000 = 10000, 100 × 100 = 10000.","10000원 — 만 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#9','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',4,'essay','teacher','10000원짜리 물건을 사려고 1000원짜리 지폐 6장과 100원짜리 동전 25개를 모았어요. 얼마가 더 있어야 하는지 풀이 과정과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u1-C1","difficulty":4,"kind":"essay","stem":"10000원짜리 물건을 사려고 1000원짜리 지폐 6장과 100원짜리 동전 25개를 모았어요. 얼마가 더 있어야 하는지 풀이 과정과 함께 써 보세요.","answer_guide":{"answer":"예: 1000원 6장은 6000원, 100원 25개는 2500원이므로 모은 돈은 8500원이다. 10000 − 8500 = 1500이므로 1500원이 더 있어야 한다.","scoring_points":["6000원과 2500원을 구했는가","8500원을 구했는가","1500원이 더 있어야 한다고 답했는가"]},"explanation":["6000 + 2500 = 8500.","10000 − 8500 = 1500.","1500원이 더 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L02_challenge#10','math',4,1,'u1','L02','g4_1_math_u1_L02_challenge','lesson_challenge','M4-1-u1-C1',4,'sa','auto','지유는 학용품을 사려고 1000원짜리 지폐 4장, 500원짜리 동전 7개, 100원짜리 동전 18개, 10원짜리 동전 30개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u1-C1","difficulty":4,"kind":"sa","stem":"지유는 학용품을 사려고 1000원짜리 지폐 4장, 500원짜리 동전 7개, 100원짜리 동전 18개, 10원짜리 동전 30개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["400"],"explanation":["가진 돈: 4000원 + 3500원 + 1800원 + 300원 = 9600원.","10000 − 9600 = 400.","400원이 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"지유는 학용품을 사려고 5000원짜리 지폐 1장, 500원짜리 동전 5개, 100원짜리 동전 14개, 50원짜리 동전 6개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["800"],"explanation":["가진 돈: 5000원 + 2500원 + 1400원 + 300원 = 9200원.","10000 − 9200 = 800.","800원이 더 있어야 해요."],"asset":null},{"stem":"지유는 학용품을 사려고 1000원짜리 지폐 3장, 500원짜리 동전 9개, 100원짜리 동전 11개, 10원짜리 동전 40개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["1000"],"explanation":["가진 돈: 3000원 + 4500원 + 1100원 + 400원 = 9000원.","10000 − 9000 = 1000.","1000원이 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_basic#1','math',4,1,'u1','L03','g4_1_math_u1_L03_basic','lesson_basic','M4-1-u1-C2',1,'mc','auto','10000이 3개, 1000이 5개, 100이 4개, 10이 7개, 1이 6개인 수는 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X18']::text[],true,'{"seq":1,"concept":"M4-1-u1-C2","difficulty":1,"kind":"mc","stem":"10000이 3개, 1000이 5개, 100이 4개, 10이 7개, 1이 6개인 수는 얼마인가요?","options":[{"t":"35476","correct":true},{"t":"354760","mis":"M4-1-u1-X16"},{"t":"34576","mis":"M4-1-u1-X18"},{"t":"35746","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","30000 + 5000 + 400 + 70 + 6 = 35476.","「삼만 오천사백칠십육」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"10000이 5개, 1000이 2개, 100이 8개, 10이 1개, 1이 3개인 수는 얼마인가요?","options":[{"t":"52813","correct":true},{"t":"528130","mis":"M4-1-u1-X16"},{"t":"58213","mis":"M4-1-u1-X18"},{"t":"52183","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","50000 + 2000 + 800 + 10 + 3 = 52813.","「오만 이천팔백십삼」이라고 읽어요."],"asset":null},{"stem":"10000이 4개, 1000이 7개, 100이 2개, 10이 6개, 1이 9개인 수는 얼마인가요?","options":[{"t":"47269","correct":true},{"t":"472690","mis":"M4-1-u1-X16"},{"t":"42769","mis":"M4-1-u1-X18"},{"t":"47629","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","40000 + 7000 + 200 + 60 + 9 = 47269.","「사만 칠천이백육십구」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_basic#2','math',4,1,'u1','L03','g4_1_math_u1_L03_basic','lesson_basic','M4-1-u1-C3',1,'sa','auto','68263에서 천의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u1-C3","difficulty":1,"kind":"sa","stem":"68263에서 천의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.","answer":["8000"],"explanation":["천의 자리 숫자는 8이에요.","천의 자리 8은 8 × 1000 = 8000을 나타내요.","숫자 8과 값 8000은 달라요 — 자리 이름만큼 0을 붙여요."],"variant_rule":{"alt":[{"stem":"35476에서 백의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["백의 자리 숫자는 4예요.","백의 자리 4는 4 × 100 = 400을 나타내요.","숫자 4와 값 400은 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null},{"stem":"74815에서 십의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["십의 자리 숫자는 1이에요.","십의 자리 1은 1 × 10 = 10을 나타내요.","숫자 1과 값 10은 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_basic#3','math',4,1,'u1','L03','g4_1_math_u1_L03_basic','lesson_basic','M4-1-u1-C3',1,'sa','auto','35476에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u1-C3","difficulty":1,"kind":"sa","stem":"35476에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천의 자리는 오른쪽에서 4번째 자리예요.","천의 자리 숫자는 5예요."],"variant_rule":{"alt":[{"stem":"82614에서 만의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","만의 자리는 오른쪽에서 5번째 자리예요.","만의 자리 숫자는 8이에요."],"asset":null},{"stem":"49357에서 십의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","십의 자리는 오른쪽에서 2번째 자리예요.","십의 자리 숫자는 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_basic#4','math',4,1,'u1','L03','g4_1_math_u1_L03_basic','lesson_basic','M4-1-u1-C3',1,'sa','auto','18943에서 백의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u1-C3","difficulty":1,"kind":"sa","stem":"18943에서 백의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["백의 자리 숫자는 9예요.","백의 자리 9는 9 × 100 = 900을 나타내요.","숫자 9와 값 900은 달라요 — 자리 이름만큼 0을 붙여요."],"variant_rule":{"alt":[{"stem":"57401에서 천의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.","answer":["7000"],"explanation":["천의 자리 숫자는 7이에요.","천의 자리 7은 7 × 1000 = 7000을 나타내요.","숫자 7과 값 7000은 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null},{"stem":"26834에서 십의 자리 숫자가 나타내는 값은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["십의 자리 숫자는 3이에요.","십의 자리 3은 3 × 10 = 30을 나타내요.","숫자 3과 값 30은 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
