INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_challenge#2','math',4,1,'u1','L03','g4_1_math_u1_L03_challenge','lesson_challenge','M4-1-u1-C2',2,'mc','auto','서준이가 저금통을 열어 보니 10000원짜리 3장, 1000원짜리 5장, 100원짜리 4개, 10원짜리 7개, 1원짜리 6개가 있었어요. 서준이가 모은 돈은 모두 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X18']::text[],true,'{"seq":2,"concept":"M4-1-u1-C2","difficulty":2,"kind":"mc","stem":"서준이가 저금통을 열어 보니 10000원짜리 3장, 1000원짜리 5장, 100원짜리 4개, 10원짜리 7개, 1원짜리 6개가 있었어요. 서준이가 모은 돈은 모두 얼마인가요?","options":[{"t":"35476원","correct":true},{"t":"354760원","mis":"M4-1-u1-X16"},{"t":"34576원","mis":"M4-1-u1-X18"},{"t":"35746원","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","30000 + 5000 + 400 + 70 + 6 = 35476.","「삼만 오천사백칠십육」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"서준이가 저금통을 열어 보니 10000원짜리 4장, 1000원짜리 2장, 100원짜리 3개, 10원짜리 1개, 1원짜리 8개가 있었어요. 서준이가 모은 돈은 모두 얼마인가요?","options":[{"t":"42318원","correct":true},{"t":"423180원","mis":"M4-1-u1-X16"},{"t":"43218원","mis":"M4-1-u1-X18"},{"t":"42138원","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","40000 + 2000 + 300 + 10 + 8 = 42318.","「사만 이천삼백십팔」이라고 읽어요."],"asset":null},{"stem":"서준이가 저금통을 열어 보니 10000원짜리 5장, 1000원짜리 1장, 10원짜리 6개, 1원짜리 4개가 있었어요. 서준이가 모은 돈은 모두 얼마인가요?","options":[{"t":"51064원","correct":true},{"t":"5164원","mis":"M4-1-u1-X01"},{"t":"510640원","mis":"M4-1-u1-X16"},{"t":"50164원","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요 — 백의 자리는 0.","50000 + 1000 + 60 + 4 = 51064.","「오만 천육십사」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_challenge#3','math',4,1,'u1','L03','g4_1_math_u1_L03_challenge','lesson_challenge','M4-1-u1-C2',3,'mc','auto','「육만 사십」을 수로 쓰면 얼마인가요?',ARRAY['M4-1-u1-X01','M4-1-u1-X16']::text[],true,'{"seq":3,"concept":"M4-1-u1-C2","difficulty":3,"kind":"mc","stem":"「육만 사십」을 수로 쓰면 얼마인가요?","options":[{"t":"60040","correct":true},{"t":"640","mis":"M4-1-u1-X01"},{"t":"600400","mis":"M4-1-u1-X16"},{"t":"6004","mis":"M4-1-u1-X16"}],"explanation":["단위(만) 앞의 수를 네 자리씩 써요 — 빈 자리는 0.","6(만), 0040(일).","그래서 60040이에요 — 5자리 수예요."],"variant_rule":{"alt":[{"stem":"「팔만 삼백오」를 수로 쓰면 얼마인가요?","options":[{"t":"80305","correct":true},{"t":"8305","mis":"M4-1-u1-X01"},{"t":"803050","mis":"M4-1-u1-X16"},{"t":"803050000","mis":"M4-1-u1-X05"}],"explanation":["단위(만) 앞의 수를 네 자리씩 써요 — 빈 자리는 0.","8(만), 0305(일).","그래서 80305예요 — 5자리 수예요."],"asset":null},{"stem":"「칠만 구」를 수로 쓰면 얼마인가요?","options":[{"t":"70009","correct":true},{"t":"79","mis":"M4-1-u1-X01"},{"t":"700090","mis":"M4-1-u1-X16"},{"t":"700090000","mis":"M4-1-u1-X05"}],"explanation":["단위(만) 앞의 수를 네 자리씩 써요 — 빈 자리는 0.","7(만), 0009(일).","그래서 70009예요 — 5자리 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
