INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_challenge#7','math',4,1,'u1','L03','g4_1_math_u1_L03_challenge','lesson_challenge','M4-1-u1-C3',3,'error','auto','69410을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X15']::text[],true,'{"seq":7,"concept":"M4-1-u1-C3","difficulty":3,"kind":"error","stem":"69410을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「6자리 수야」","correct":true,"mis_target":"M4-1-u1-X16"},{"t":"지유 — 「69410을 「육만 구천사백십」이라고 읽어」","mis":"M4-1-u1-X15"},{"t":"은우 — 「만의 자리 숫자는 6」","mis":"M4-1-u1-X15"}],"explanation":["「육만 구천사백십」 — 5자리 수예요.","만의 자리 숫자 6은 60000을 나타내요.","도윤이 잘못 말했어요 — 네 자리씩 점 찍고 세기."],"variant_rule":{"alt":[{"stem":"35476을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「백의 자리 숫자 4는 4를 나타내」","correct":true,"mis_target":"M4-1-u1-X02"},{"t":"시아 — 「35476을 「삼만 오천사백칠십육」이라고 읽어」","mis":"M4-1-u1-X15"},{"t":"은우 — 「5자리 수야」","mis":"M4-1-u1-X15"}],"explanation":["「삼만 오천사백칠십육」 — 5자리 수예요.","백의 자리 숫자 4는 400을 나타내요.","하린이 잘못 말했어요 — 숫자 × 자리."],"asset":null},{"stem":"52738을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「6자리 수야」","correct":true,"mis_target":"M4-1-u1-X16"},{"t":"하린 — 「52738을 「오만 이천칠백삼십팔」이라고 읽어」","mis":"M4-1-u1-X15"},{"t":"도윤 — 「십의 자리 숫자는 3」","mis":"M4-1-u1-X15"}],"explanation":["「오만 이천칠백삼십팔」 — 5자리 수예요.","십의 자리 숫자 3은 30을 나타내요.","은우가 잘못 말했어요 — 네 자리씩 점 찍고 세기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_challenge#8','math',4,1,'u1','L03','g4_1_math_u1_L03_challenge','lesson_challenge','M4-1-u1-C2',4,'essay','teacher','19604를 친구가 「만 구천육백영사」라고 읽었어요. 잘못된 점을 설명하고 바르게 읽어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u1-C2","difficulty":4,"kind":"essay","stem":"19604를 친구가 「만 구천육백영사」라고 읽었어요. 잘못된 점을 설명하고 바르게 읽어 보세요.","answer_guide":{"answer":"예: 0인 십의 자리는 읽지 않아야 하는데 「영」을 넣어 읽었다. 19604는 만 구천육백사(또는 일만 구천육백사)라고 읽는다.","scoring_points":["십의 자리 0을 읽으면 안 된다고 설명했는가","만 구천육백사(일만 구천육백사)라고 바르게 읽었는가","자리 이름을 붙여 읽었는가"]},"explanation":["19604 — 만 1, 천 9, 백 6, 십 0, 일 4.","0인 자리는 읽지 않아요.","만 구천육백사."],"asset":{"type":"expr_grid","rows":[["만","천","백","십","일"],["1","9","6","0","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_challenge#9','math',4,1,'u1','L03','g4_1_math_u1_L03_challenge','lesson_challenge','M4-1-u1-C3',4,'essay','teacher','33333에서 숫자 3이 나타내는 값을 자리마다 모두 쓰고, 같은 숫자인데 값이 다른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u1-C3","difficulty":4,"kind":"essay","stem":"33333에서 숫자 3이 나타내는 값을 자리마다 모두 쓰고, 같은 숫자인데 값이 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 만의 자리 30000, 천의 자리 3000, 백의 자리 300, 십의 자리 30, 일의 자리 3. 같은 숫자라도 놓인 자리에 따라 나타내는 값이 다르기 때문이다(한 자리 왼쪽으로 갈 때마다 10배).","scoring_points":["30000·3000·300·30·3을 모두 썼는가","자리에 따라 값이 다르다고 설명했는가","왼쪽 자리로 갈수록 10배임을 말했는가"]},"explanation":["30000 + 3000 + 300 + 30 + 3 = 33333.","자리가 다르면 값도 달라요.","왼쪽으로 한 자리 갈 때마다 10배."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L03_challenge#10','math',4,1,'u1','L03','g4_1_math_u1_L03_challenge','lesson_challenge','M4-1-u1-C2',4,'sa','auto','「육만 사십」을 자릿값 표에 나타냈어요. 빈칸에 알맞은 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u1-C2","difficulty":4,"kind":"sa","stem":"「육만 사십」을 자릿값 표에 나타냈어요. 빈칸에 알맞은 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["「육만 사십」을 수로 쓰면 60040이에요.","백의 자리 숫자는 0이에요.","읽을 때 나오지 않은 자리는 0을 써요."],"asset":{"type":"expr_grid","rows":[["만","천","백","십","일"],["6","0",null,"4","0"]]},"variant_rule":{"alt":[{"stem":"「팔만 삼백오」를 자릿값 표에 나타냈어요. 빈칸에 알맞은 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["「팔만 삼백오」를 수로 쓰면 80305예요.","천의 자리 숫자는 0이에요.","읽을 때 나오지 않은 자리는 0을 써요."],"asset":{"type":"expr_grid","rows":[["만","천","백","십","일"],["8",null,"3","0","5"]]}},{"stem":"「칠만 구」를 자릿값 표에 나타냈어요. 빈칸에 알맞은 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["「칠만 구」를 수로 쓰면 70009예요.","십의 자리 숫자는 0이에요.","읽을 때 나오지 않은 자리는 0을 써요."],"asset":{"type":"expr_grid","rows":[["만","천","백","십","일"],["7","0","0",null,"9"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L04_basic#1','math',4,1,'u1','L04','g4_1_math_u1_L04_basic','lesson_basic','M4-1-u1-C4',1,'mc','auto','10000이 10개인 수는 얼마인가요?',ARRAY['M4-1-u1-X07','M4-1-u1-X16']::text[],true,'{"seq":1,"concept":"M4-1-u1-C4","difficulty":1,"kind":"mc","stem":"10000이 10개인 수는 얼마인가요?","options":[{"t":"100000","correct":true},{"t":"10000","mis":"M4-1-u1-X07"},{"t":"1000000","mis":"M4-1-u1-X07"},{"t":"1000","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개인 수는 10000 × 10으로 구해요.","10000 × 10 = 100000 — 0을 5개 써요.","수로 쓰면 100000, 「십만」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"10000이 100개인 수는 얼마인가요?","options":[{"t":"1000000","correct":true},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"10000000","mis":"M4-1-u1-X07"},{"t":"10000","mis":"M4-1-u1-X16"}],"explanation":["10000이 100개인 수는 10000 × 100으로 구해요.","10000 × 100 = 1000000 — 0을 6개 써요.","수로 쓰면 1000000, 「백만」이라고 읽어요."],"asset":null},{"stem":"10000이 1000개인 수는 얼마인가요?","options":[{"t":"10000000","correct":true},{"t":"1000000","mis":"M4-1-u1-X07"},{"t":"100000000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X16"}],"explanation":["10000이 1000개인 수는 10000 × 1000으로 구해요.","10000 × 1000 = 10000000 — 0을 7개 써요.","수로 쓰면 10000000, 「천만」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L04_basic#2','math',4,1,'u1','L04','g4_1_math_u1_L04_basic','lesson_basic','M4-1-u1-C4',1,'mc','auto','10000이 10개인 수를 무엇이라고 하나요?',ARRAY['M4-1-u1-X07','M4-1-u1-X16']::text[],true,'{"seq":2,"concept":"M4-1-u1-C4","difficulty":1,"kind":"mc","stem":"10000이 10개인 수를 무엇이라고 하나요?","options":[{"t":"십만","correct":true},{"t":"백만","mis":"M4-1-u1-X07"},{"t":"만","mis":"M4-1-u1-X07"},{"t":"천만","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개 모이면 한 자리 위가 돼요.","10000 × 10 = 100000.","100000은 「십만」이에요."],"variant_rule":{"alt":[{"stem":"10000이 100개인 수를 무엇이라고 하나요?","options":[{"t":"백만","correct":true},{"t":"천만","mis":"M4-1-u1-X07"},{"t":"십만","mis":"M4-1-u1-X07"},{"t":"억","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개 모이면 한 자리 위가 돼요.","10000 × 100 = 1000000.","1000000은 「백만」이에요."],"asset":null},{"stem":"10000이 1000개인 수를 무엇이라고 하나요?","options":[{"t":"천만","correct":true},{"t":"억","mis":"M4-1-u1-X07"},{"t":"백만","mis":"M4-1-u1-X07"},{"t":"십억","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개 모이면 한 자리 위가 돼요.","10000 × 1000 = 10000000.","10000000은 「천만」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L04_basic#3','math',4,1,'u1','L04','g4_1_math_u1_L04_basic','lesson_basic','M4-1-u1-C4',1,'mc','auto','52780000에서 천만의 자리 숫자가 나타내는 값은 얼마인가요?',ARRAY['M4-1-u1-X02','M4-1-u1-X03']::text[],true,'{"seq":3,"concept":"M4-1-u1-C4","difficulty":1,"kind":"mc","stem":"52780000에서 천만의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"50000000","correct":true},{"t":"5","mis":"M4-1-u1-X02"},{"t":"5000000","mis":"M4-1-u1-X03"},{"t":"500000000","mis":"M4-1-u1-X03"}],"explanation":["천만의 자리 숫자는 5예요.","천만의 자리 5는 5 × 1000만 = 50000000을 나타내요.","숫자 5와 값 50000000은 달라요 — 자리 이름만큼 0을 붙여요."],"variant_rule":{"alt":[{"stem":"37160000에서 백만의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"7000000","correct":true},{"t":"7","mis":"M4-1-u1-X02"},{"t":"700000","mis":"M4-1-u1-X03"},{"t":"70000000","mis":"M4-1-u1-X03"}],"explanation":["백만의 자리 숫자는 7이에요.","백만의 자리 7은 7 × 100만 = 7000000을 나타내요.","숫자 7과 값 7000000은 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null},{"stem":"84520000에서 십만의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"500000","correct":true},{"t":"5","mis":"M4-1-u1-X02"},{"t":"50000","mis":"M4-1-u1-X03"},{"t":"5000000","mis":"M4-1-u1-X03"}],"explanation":["십만의 자리 숫자는 5예요.","십만의 자리 5는 5 × 10만 = 500000을 나타내요.","숫자 5와 값 500000은 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
