INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L04_challenge#4','math',4,1,'u1','L04','g4_1_math_u1_L04_challenge','lesson_challenge','M4-1-u1-C5',3,'ox','auto','325700000을 「삼천이백오십칠억」이라고 읽어요.',ARRAY['M4-1-u1-X04']::text[],true,'{"seq":4,"concept":"M4-1-u1-C5","difficulty":3,"kind":"ox","stem":"325700000을 「삼천이백오십칠억」이라고 읽어요.","answer":"X","reason_options":[{"t":"일의 자리부터 네 자리씩 끊어야 해서","correct":true},{"t":"앞에서부터 네 자리씩 끊어 읽어서","mis":"M4-1-u1-X04"}],"mis":"M4-1-u1-X04","explanation":["일의 자리부터 네 자리씩 끊어요.","325700000은 「삼억 이천오백칠십만」이라고 읽어요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"40801000을 「사천영팔십만 천」이라고 읽어요.","answer":"X","reason_options":[{"t":"0인 자리는 읽지 않아서","correct":true},{"t":"0인 자리도 「영」으로 읽어야 해서","mis":"M4-1-u1-X06"}],"explanation":["일의 자리부터 네 자리씩 끊어요.","40801000은 「사천팔십만 천」이라고 읽어요.","그래서 틀렸어요."],"asset":null},{"stem":"52780000을 「오천이백칠십팔만」이라고 읽어요.","answer":"O","reason_options":[{"t":"네 자리씩 끊어 읽으면 그렇게 읽어서","correct":true},{"t":"0인 자리도 「영」으로 읽어야 해서","mis":"M4-1-u1-X06"}],"explanation":["일의 자리부터 네 자리씩 끊어요.","52780000은 「오천이백칠십팔만」이라고 읽어요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
