INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L04_challenge#8','math',4,1,'u1','L04','g4_1_math_u1_L04_challenge','lesson_challenge','M4-1-u1-C5',4,'essay','teacher','52780000을 읽는 방법을 「네 자리씩 끊기」로 설명하고, 천만의 자리 숫자가 나타내는 값도 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u1-C5","difficulty":4,"kind":"essay","stem":"52780000을 읽는 방법을 「네 자리씩 끊기」로 설명하고, 천만의 자리 숫자가 나타내는 값도 써 보세요.","answer_guide":{"answer":"예: 일의 자리부터 네 자리씩 끊으면 5278 / 0000이다. 앞 묶음 5278에 「만」을 붙여 오천이백칠십팔만이라고 읽고, 0000은 읽지 않는다. 천만의 자리 숫자 5는 50000000(오천만)을 나타낸다.","scoring_points":["일의 자리부터 네 자리씩 끊었는가","오천이백칠십팔만이라고 읽었는가","50000000(오천만)을 썼는가"]},"explanation":["5278 / 0000.","오천이백칠십팔만.","천만의 자리 5 → 50000000."],"asset":{"type":"expr_grid","rows":[["만","일"],["5278","0000"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L04_challenge#9','math',4,1,'u1','L04','g4_1_math_u1_L04_challenge','lesson_challenge','M4-1-u1-C4',4,'essay','teacher','10000원짜리 지폐로 100만 원과 1000만 원을 만들려면 각각 몇 장이 필요한지 쓰고, 두 수의 관계를 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u1-C4","difficulty":4,"kind":"essay","stem":"10000원짜리 지폐로 100만 원과 1000만 원을 만들려면 각각 몇 장이 필요한지 쓰고, 두 수의 관계를 설명해 보세요.","answer_guide":{"answer":"예: 100만 원은 10000원짜리 100장, 1000만 원은 10000원짜리 1000장이 필요하다. 1000만은 100만의 10배이므로 필요한 장수도 10배이다.","scoring_points":["100장을 구했는가","1000장을 구했는가","10배 관계를 설명했는가"]},"explanation":["10000이 100개 → 100만.","10000이 1000개 → 1000만.","1000만은 100만의 10배."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
