INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_basic#7','math',4,1,'u1','L05','g4_1_math_u1_L05_basic','lesson_basic','M4-1-u1-C7',2,'sa','auto','「칠천삼백구십이조」는 조가 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u1-C7","difficulty":2,"kind":"sa","stem":"「칠천삼백구십이조」는 조가 몇 개인 수인가요? 숫자로 쓰세요.","answer":["7392"],"explanation":["조 앞에 있는 수만 세요.","「칠천삼백구십이조」 = 7392조.","조가 7392개 — 답은 7392예요."],"variant_rule":{"alt":[{"stem":"「사천백팔십오조」는 조가 몇 개인 수인가요? 숫자로 쓰세요.","answer":["4185"],"explanation":["조 앞에 있는 수만 세요.","「사천백팔십오조」 = 4185조.","조가 4185개 — 답은 4185예요."],"asset":null},{"stem":"「이천칠백육조」는 조가 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2706"],"explanation":["조 앞에 있는 수만 세요.","「이천칠백육조」 = 2706조.","조가 2706개 — 답은 2706이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_basic#8','math',4,1,'u1','L05','g4_1_math_u1_L05_basic','lesson_basic','M4-1-u1-C6',2,'ox','auto','1억은 100만이 10개인 수예요.',ARRAY['M4-1-u1-X07']::text[],true,'{"seq":8,"concept":"M4-1-u1-C6","difficulty":2,"kind":"ox","stem":"1억은 100만이 10개인 수예요.","answer":"X","reason_options":[{"t":"100만이 10개면 1000만이라서","correct":true},{"t":"100만이 10개 모이면 억이 되어서","mis":"M4-1-u1-X07"}],"mis":"M4-1-u1-X07","explanation":["100만이 10개면 1000만이에요.","1억은 1000만이 10개인 수예요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"1억은 1000만이 10개인 수예요.","answer":"O","reason_options":[{"t":"1000만 × 10 = 1억이라서","correct":true},{"t":"1000만이 100개여야 1억이라서","mis":"M4-1-u1-X07"}],"explanation":["1000만이 10개 모이면 1억이에요.","1억 = 100000000.","그래서 맞아요."],"asset":null},{"stem":"1조는 1000억이 10개인 수예요.","answer":"O","reason_options":[{"t":"1000억 × 10 = 1조라서","correct":true},{"t":"1000억이 100개여야 1조라서","mis":"M4-1-u1-X07"}],"explanation":["1000억이 10개 모이면 1조예요.","1조 = 1000000000000.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_basic#9','math',4,1,'u1','L05','g4_1_math_u1_L05_basic','lesson_basic','M4-1-u1-C6',2,'sa','auto','억을 수로 쓰면 1 뒤에 0을 몇 개 써야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u1-C6","difficulty":2,"kind":"sa","stem":"억을 수로 쓰면 1 뒤에 0을 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["만은 0이 4개 — 10000.","억 = 100000000.","0은 8개예요."],"variant_rule":{"alt":[{"stem":"조를 수로 쓰면 1 뒤에 0을 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["만은 0이 4개 — 10000.","조 = 1000000000000.","0은 12개예요."],"asset":null},{"stem":"십억을 수로 쓰면 1 뒤에 0을 몇 개 써야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["만은 0이 4개 — 10000.","십억 = 1000000000.","0은 9개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
