INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#1','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C6',2,'sa','auto','억은 천만의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u1-C6","difficulty":2,"kind":"sa","stem":"억은 천만의 몇 배인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["천만이 10개 모이면 억이에요.","10000000 × 10 = 100000000.","10배예요."],"variant_rule":{"alt":[{"stem":"억은 백만의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["백만이 100개 모이면 억이에요.","1000000 × 100 = 100000000.","100배예요."],"asset":null},{"stem":"조는 천억의 몇 배인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["천억이 10개 모이면 조예요.","100000000000 × 10 = 1000000000000.","10배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
