INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#3','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C6',3,'mc','auto','「삼백억 팔천만」을 수로 쓰면 얼마인가요?',ARRAY['M4-1-u1-X01','M4-1-u1-X16']::text[],true,'{"seq":3,"concept":"M4-1-u1-C6","difficulty":3,"kind":"mc","stem":"「삼백억 팔천만」을 수로 쓰면 얼마인가요?","options":[{"t":"30080000000","correct":true},{"t":"3008000","mis":"M4-1-u1-X01"},{"t":"300800000000","mis":"M4-1-u1-X16"},{"t":"3008000000","mis":"M4-1-u1-X16"}],"explanation":["단위(억·만) 앞의 수를 네 자리씩 써요 — 빈 자리는 0.","300(억), 8000(만), 0000(일).","그래서 30080000000이에요 — 11자리 수예요."],"variant_rule":{"alt":[{"stem":"「오천사십억 이십만」을 수로 쓰면 얼마인가요?","options":[{"t":"504000200000","correct":true},{"t":"504020","mis":"M4-1-u1-X01"},{"t":"5040002000000","mis":"M4-1-u1-X16"},{"t":"50400020000","mis":"M4-1-u1-X16"}],"explanation":["단위(억·만) 앞의 수를 네 자리씩 써요 — 빈 자리는 0.","5040(억), 0020(만), 0000(일).","그래서 504000200000이에요 — 12자리 수예요."],"asset":null},{"stem":"「칠십억 육만」을 수로 쓰면 얼마인가요?","options":[{"t":"7000060000","correct":true},{"t":"706","mis":"M4-1-u1-X01"},{"t":"70000600000","mis":"M4-1-u1-X16"},{"t":"700006000","mis":"M4-1-u1-X16"}],"explanation":["단위(억·만) 앞의 수를 네 자리씩 써요 — 빈 자리는 0.","70(억), 0006(만), 0000(일).","그래서 7000060000이에요 — 10자리 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#4','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C7',3,'sa','auto','나라의 1년 예산이 638조 7000억 원이에요. 이 돈을 수로 쓰면 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u1-C7","difficulty":3,"kind":"sa","stem":"나라의 1년 예산이 638조 7000억 원이에요. 이 돈을 수로 쓰면 몇 자리 수인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["638조 7000억을 수로 쓰면 638700000000000이에요.","네 자리씩: 638 / 7000 / 0000 / 0000.","모두 15자리예요."],"variant_rule":{"alt":[{"stem":"나라의 1년 예산이 5조 4320억 원이에요. 이 돈을 수로 쓰면 몇 자리 수인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["5조 4320억을 수로 쓰면 5432000000000이에요.","네 자리씩: 5 / 4320 / 0000 / 0000.","모두 13자리예요."],"asset":null},{"stem":"나라의 1년 예산이 71조 2500억 원이에요. 이 돈을 수로 쓰면 몇 자리 수인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["71조 2500억을 수로 쓰면 71250000000000이에요.","네 자리씩: 71 / 2500 / 0000 / 0000.","모두 14자리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#5','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C6',3,'error','auto','325700000000을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u1-X05','M4-1-u1-X15']::text[],true,'{"seq":5,"concept":"M4-1-u1-C6","difficulty":3,"kind":"error","stem":"325700000000을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「삼천이백오십칠만이에요」","correct":true,"mis_target":"M4-1-u1-X05"},{"t":"은우 — 「12자리 수예요」","mis":"M4-1-u1-X15"},{"t":"건우 — 「억이 3257개보다 많아요」","mis":"M4-1-u1-X15"}],"explanation":["네 자리씩 끊으면 3257 / 0000 / 0000.","「삼천이백오십칠억」 — 12자리, 억이 3257개보다 조금 많아요.","도윤이 잘못 말했어요 — 네 자리마다 만→억→조."],"variant_rule":{"alt":[{"stem":"148600000000을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「11자리 수예요」","correct":true,"mis_target":"M4-1-u1-X16"},{"t":"시아 — 「천사백팔십육억이에요」","mis":"M4-1-u1-X15"},{"t":"은우 — 「억이 1486개보다 많아요」","mis":"M4-1-u1-X15"}],"explanation":["네 자리씩 끊으면 1486 / 0000 / 0000.","「천사백팔십육억」 — 12자리, 억이 1486개보다 조금 많아요.","하린이 잘못 말했어요 — 네 자리씩 점 찍고 세기."],"asset":null},{"stem":"530290000000을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「억이 53020개보다 많아요」","correct":true,"mis_target":"M4-1-u1-X17"},{"t":"하린 — 「오천삼백이억 구천만이에요」","mis":"M4-1-u1-X15"},{"t":"도윤 — 「12자리 수예요」","mis":"M4-1-u1-X15"}],"explanation":["네 자리씩 끊으면 5302 / 9000 / 0000.","「오천삼백이억 구천만」 — 12자리, 억이 5302개보다 조금 많아요.","은우가 잘못 말했어요 — 단위 앞 네 자리만."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#6','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C7',3,'mc','auto','145932100000000에서 십조의 자리 숫자가 나타내는 값은 얼마인가요?',ARRAY['M4-1-u1-X02','M4-1-u1-X03']::text[],true,'{"seq":6,"concept":"M4-1-u1-C7","difficulty":3,"kind":"mc","stem":"145932100000000에서 십조의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"40000000000000","correct":true},{"t":"4","mis":"M4-1-u1-X02"},{"t":"4000000000000","mis":"M4-1-u1-X03"},{"t":"400000000000000","mis":"M4-1-u1-X03"}],"explanation":["십조의 자리 숫자는 4예요.","십조의 자리 4는 4 × 10조 = 40000000000000를 나타내요.","숫자 4와 값 40000000000000는 달라요 — 자리 이름만큼 0을 붙여요."],"variant_rule":{"alt":[{"stem":"27384600000000에서 조의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"7000000000000","correct":true},{"t":"7","mis":"M4-1-u1-X02"},{"t":"700000000000","mis":"M4-1-u1-X03"},{"t":"70000000000000","mis":"M4-1-u1-X03"}],"explanation":["조의 자리 숫자는 7이에요.","조의 자리 7은 7 × 1조 = 7000000000000를 나타내요.","숫자 7과 값 7000000000000는 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null},{"stem":"308215000000000에서 백조의 자리 숫자가 나타내는 값은 얼마인가요?","options":[{"t":"300000000000000","correct":true},{"t":"3","mis":"M4-1-u1-X02"},{"t":"30000000000000","mis":"M4-1-u1-X03"},{"t":"3000000000000000","mis":"M4-1-u1-X03"}],"explanation":["백조의 자리 숫자는 3이에요.","백조의 자리 3은 3 × 100조 = 300000000000000를 나타내요.","숫자 3과 값 300000000000000는 달라요 — 자리 이름만큼 0을 붙여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#7','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C7',3,'mc','auto','네 자리씩 끊어 나타낸 표를 보고 수를 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-1-u1-X05','M4-1-u1-X01','M4-1-u1-X16']::text[],true,'{"seq":7,"concept":"M4-1-u1-C7","difficulty":3,"kind":"mc","stem":"네 자리씩 끊어 나타낸 표를 보고 수를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"백사십오조 구천삼백이십일억","correct":true},{"t":"백사십오억 구천삼백이십일만","mis":"M4-1-u1-X05"},{"t":"백사십오만 구천삼백이십일","mis":"M4-1-u1-X01"},{"t":"천사백오십구조 삼천이백십억","mis":"M4-1-u1-X16"}],"explanation":["칸마다 네 자리 수를 읽고 칸 이름(조·억·만·일)을 붙여요.","0000인 칸은 읽지 않아요.","「백사십오조 구천삼백이십일억」이에요."],"asset":{"type":"expr_grid","rows":[["조","억","만","일"],["145","9321","0000","0000"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 네 자리씩 끊어 나타낸 표를 보고 수를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"이십조 오천칠억","correct":true},{"t":"이십조 오천영영칠억","mis":"M4-1-u1-X06"},{"t":"이십억 오천칠만","mis":"M4-1-u1-X05"},{"t":"이십만 오천칠","mis":"M4-1-u1-X01"}],"explanation":["칸마다 네 자리 수를 읽고 칸 이름(조·억·만·일)을 붙여요.","0000인 칸은 읽지 않아요.","「이십조 오천칠억」이에요."],"asset":{"type":"expr_grid","rows":[["조","억","만","일"],["20","5007","0000","0000"]]}},{"stem":"이번에는 다른 수예요. 네 자리씩 끊어 나타낸 표를 보고 수를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"칠천삼백구십이조 사백만","correct":true},{"t":"칠천삼백구십이억 사백","mis":"M4-1-u1-X05"},{"t":"칠백삼십구만 이천사백","mis":"M4-1-u1-X01"},{"t":"칠천구백삼십이조 사백만","mis":"M4-1-u1-X18"}],"explanation":["칸마다 네 자리 수를 읽고 칸 이름(조·억·만·일)을 붙여요.","0000인 칸은 읽지 않아요.","「칠천삼백구십이조 사백만」이에요."],"asset":{"type":"expr_grid","rows":[["조","억","만","일"],["7392","0000","0400","0000"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EX