INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#8','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C7',4,'essay','teacher','145932100000000을 네 자리씩 끊어 읽는 방법을 설명하고, 바르게 읽어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u1-C7","difficulty":4,"kind":"essay","stem":"145932100000000을 네 자리씩 끊어 읽는 방법을 설명하고, 바르게 읽어 보세요.","answer_guide":{"answer":"예: 일의 자리부터 네 자리씩 끊으면 145 / 9321 / 0000 / 0000이다. 앞에서부터 조·억·만·일 단위를 붙이고 0000인 만·일 묶음은 읽지 않는다. 백사십오조 구천삼백이십일억이라고 읽는다.","scoring_points":["일의 자리부터 네 자리씩 끊었는가","조·억 단위를 바르게 붙였는가","백사십오조 구천삼백이십일억이라고 읽었는가"]},"explanation":["145 / 9321 / 0000 / 0000.","조·억·만·일 — 0000은 읽지 않아요.","백사십오조 구천삼백이십일억."],"asset":{"type":"expr_grid","rows":[["조","억","만","일"],["145","9321","0000","0000"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L05_challenge#9','math',4,1,'u1','L05','g4_1_math_u1_L05_challenge','lesson_challenge','M4-1-u1-C6',4,'essay','teacher','1억은 10000원짜리 지폐로 몇 장인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u1-C6","difficulty":4,"kind":"essay","stem":"1억은 10000원짜리 지폐로 몇 장인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 10000장이다. 10000이 10000개이면 1억이기 때문이다(10000 × 10000 = 100000000). 또는 1억은 1000만이 10개이고 1000만은 10000이 1000개이므로 10000이 10000개이다.","scoring_points":["10000장이라고 답했는가","10000 × 10000 = 1억임을 설명했는가","만이 만 개 모이면 억이라는 관계를 썼는가"]},"explanation":["만이 10000개 → 1억.","10000 × 10000 = 100000000.","10000장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
