INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_basic#8','math',4,1,'u1','L06','g4_1_math_u1_L06_basic','lesson_basic','M4-1-u1-C8',2,'ox','auto','10만씩 뛰어 세면 만의 자리 숫자가 1씩 커져요.',ARRAY['M4-1-u1-X08']::text[],true,'{"seq":8,"concept":"M4-1-u1-C8","difficulty":2,"kind":"ox","stem":"10만씩 뛰어 세면 만의 자리 숫자가 1씩 커져요.","answer":"X","reason_options":[{"t":"십만의 자리 숫자가 바뀌어야 해서","correct":true},{"t":"만의 자리가 바뀌는 게 맞아서","mis":"M4-1-u1-X08"}],"mis":"M4-1-u1-X08","explanation":["10만은 십만의 자리 숫자 1이에요.","10만씩 뛰면 십만의 자리 숫자가 1씩 커져요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"100만씩 뛰어 세면 백만의 자리 숫자가 1씩 커져요.","answer":"O","reason_options":[{"t":"백만의 자리 숫자 1만큼 뛰어서","correct":true},{"t":"100만씩 뛰면 그 아래 자리가 바뀌어서","mis":"M4-1-u1-X08"}],"explanation":["100만은 백만의 자리 숫자 1이에요.","100만씩 뛰면 백만의 자리 숫자가 1씩 커져요.","그래서 맞아요."],"asset":null},{"stem":"1000만씩 뛰어 세면 백만의 자리 숫자가 1씩 커져요.","answer":"X","reason_options":[{"t":"천만의 자리 숫자가 바뀌어야 해서","correct":true},{"t":"백만의 자리가 바뀌는 게 맞아서","mis":"M4-1-u1-X08"}],"explanation":["1000만은 천만의 자리 숫자 1이에요.","1000만씩 뛰면 천만의 자리 숫자가 1씩 커져요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_basic#9','math',4,1,'u1','L06','g4_1_math_u1_L06_basic','lesson_basic','M4-1-u1-C8',2,'sa','auto','건우는 지금 20000원이 있고, 매달 10000원씩 저금해요. 몇 달 뒤에 모은 돈이 70000원이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u1-C8","difficulty":2,"kind":"sa","stem":"건우는 지금 20000원이 있고, 매달 10000원씩 저금해요. 몇 달 뒤에 모은 돈이 70000원이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["20000에서 10000씩 뛰어 세어요.","20000 − 30000 − 40000 − 50000 − 60000 − 70000.","5번 뛰어 세었으니 5달 뒤예요."],"variant_rule":{"alt":[{"stem":"건우는 지금 30000원이 있고, 매달 20000원씩 저금해요. 몇 달 뒤에 모은 돈이 150000원이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["30000에서 20000씩 뛰어 세어요.","30000 − 50000 − 70000 − 90000 − 110000 − 130000 ….","6번 뛰어 세었으니 6달 뒤예요."],"asset":null},{"stem":"건우는 지금 50000원이 있고, 매달 10000원씩 저금해요. 몇 달 뒤에 모은 돈이 120000원이 되나요? 숫자로 쓰세요.","answer":["7"],"explanation":["50000에서 10000씩 뛰어 세어요.","50000 − 60000 − 70000 − 80000 − 90000 − 100000 ….","7번 뛰어 세었으니 7달 뒤예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
