INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_challenge#5','math',4,1,'u1','L06','g4_1_math_u1_L06_challenge','lesson_challenge','M4-1-u1-C8',3,'mc','auto','1200000000에서 1억씩 거꾸로 5번 뛰어 센 수는 얼마인가요?',ARRAY['M4-1-u1-X18','M4-1-u1-X10']::text[],true,'{"seq":5,"concept":"M4-1-u1-C8","difficulty":3,"kind":"mc","stem":"1200000000에서 1억씩 거꾸로 5번 뛰어 센 수는 얼마인가요?","options":[{"t":"700000000","correct":true},{"t":"800000000","mis":"M4-1-u1-X18"},{"t":"600000000","mis":"M4-1-u1-X18"},{"t":"1700000000","mis":"M4-1-u1-X10"}],"explanation":["1억씩 5번이면 모두 5억만큼 작아져요.","1200000000 − 500000000 = 700000000.","답은 700000000이에요."],"variant_rule":{"alt":[{"stem":"3050000에서 10000씩 거꾸로 7번 뛰어 센 수는 얼마인가요?","options":[{"t":"2980000","correct":true},{"t":"2990000","mis":"M4-1-u1-X18"},{"t":"2970000","mis":"M4-1-u1-X18"},{"t":"2350000","mis":"M4-1-u1-X08"}],"explanation":["10000씩 7번이면 모두 70000만큼 작아져요.","3050000 − 70000 = 2980000.","답은 2980000이에요."],"asset":null},{"stem":"70040000000에서 10억씩 거꾸로 8번 뛰어 센 수는 얼마인가요?","options":[{"t":"62040000000","correct":true},{"t":"63040000000","mis":"M4-1-u1-X18"},{"t":"61040000000","mis":"M4-1-u1-X18"},{"t":"78040000000","mis":"M4-1-u1-X10"}],"explanation":["10억씩 8번이면 모두 80억만큼 작아져요.","70040000000 − 8000000000 = 62040000000.","답은 62040000000이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_challenge#6','math',4,1,'u1','L06','g4_1_math_u1_L06_challenge','lesson_challenge','M4-1-u1-C8',3,'sa','auto','건우는 지금 35000원이 있고, 매달 15000원씩 저금해요. 몇 달 뒤에 모은 돈이 125000원이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u1-C8","difficulty":3,"kind":"sa","stem":"건우는 지금 35000원이 있고, 매달 15000원씩 저금해요. 몇 달 뒤에 모은 돈이 125000원이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["35000에서 15000씩 뛰어 세어요.","35000 − 50000 − 65000 − 80000 − 95000 − 110000 ….","6번 뛰어 세었으니 6달 뒤예요."],"variant_rule":{"alt":[{"stem":"건우는 지금 48000원이 있고, 매달 12000원씩 저금해요. 몇 달 뒤에 모은 돈이 120000원이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["48000에서 12000씩 뛰어 세어요.","48000 − 60000 − 72000 − 84000 − 96000 − 108000 ….","6번 뛰어 세었으니 6달 뒤예요."],"asset":null},{"stem":"건우는 지금 60000원이 있고, 매달 25000원씩 저금해요. 몇 달 뒤에 모은 돈이 210000원이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["60000에서 25000씩 뛰어 세어요.","60000 − 85000 − 110000 − 135000 − 160000 − 185000 ….","6번 뛰어 세었으니 6달 뒤예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_challenge#7','math',4,1,'u1','L06','g4_1_math_u1_L06_challenge','lesson_challenge','M4-1-u1-C8',3,'ox','auto','1억씩 뛰어 세면 천만의 자리 숫자가 1씩 커져요.',ARRAY['M4-1-u1-X08']::text[],true,'{"seq":7,"concept":"M4-1-u1-C8","difficulty":3,"kind":"ox","stem":"1억씩 뛰어 세면 천만의 자리 숫자가 1씩 커져요.","answer":"X","reason_options":[{"t":"억의 자리 숫자가 바뀌어야 해서","correct":true},{"t":"천만의 자리가 바뀌는 게 맞아서","mis":"M4-1-u1-X08"}],"mis":"M4-1-u1-X08","explanation":["1억은 억의 자리 숫자 1이에요.","1억씩 뛰면 억의 자리 숫자가 1씩 커져요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"10억씩 뛰어 세면 십억의 자리 숫자가 1씩 커져요.","answer":"O","reason_options":[{"t":"십억의 자리 숫자 1만큼 뛰어서","correct":true},{"t":"10억씩 뛰면 그 아래 자리가 바뀌어서","mis":"M4-1-u1-X08"}],"explanation":["10억은 십억의 자리 숫자 1이에요.","10억씩 뛰면 십억의 자리 숫자가 1씩 커져요.","그래서 맞아요."],"asset":null},{"stem":"1조씩 뛰어 세면 조의 자리 숫자가 1씩 커져요.","answer":"O","reason_options":[{"t":"조의 자리 숫자 1만큼 뛰어서","correct":true},{"t":"1조씩 뛰면 그 아래 자리가 바뀌어서","mis":"M4-1-u1-X08"}],"explanation":["1조는 조의 자리 숫자 1이에요.","1조씩 뛰면 조의 자리 숫자가 1씩 커져요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_challenge#8','math',4,1,'u1','L06','g4_1_math_u1_L06_challenge','lesson_challenge','M4-1-u1-C8',4,'essay','teacher','건우는 매달 20000원씩, 동생은 매달 10000원씩 저금해요. 지금 둘 다 0원이라면 몇 달 뒤에 건우가 모은 돈이 100000원이 되는지 뛰어 세기로 구하고, 그때 동생은 얼마를 모았는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u1-C8","difficulty":4,"kind":"essay","stem":"건우는 매달 20000원씩, 동생은 매달 10000원씩 저금해요. 지금 둘 다 0원이라면 몇 달 뒤에 건우가 모은 돈이 100000원이 되는지 뛰어 세기로 구하고, 그때 동생은 얼마를 모았는지 써 보세요.","answer_guide":{"answer":"예: 20000 − 40000 − 60000 − 80000 − 100000으로 5번 뛰어 세므로 5달 뒤이다. 동생은 10000씩 5번 뛰어 세어 50000원을 모았다.","scoring_points":["20000씩 뛰어 세었는가","5달 뒤라고 답했는가","동생이 50000원을 모았다고 답했는가"]},"explanation":["20000씩: 20000, 40000, 60000, 80000, 100000.","5번 → 5달 뒤.","동생 10000 × 5 = 50000원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_challenge#9','math',4,1,'u1','L06','g4_1_math_u1_L06_challenge','lesson_challenge','M4-1-u1-C8',4,'essay','teacher','9800만에서 1000만씩 세 번 뛰어 센 수들을 쓰고, 자리가 넘어갈 때 어떻게 되는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u1-C8","difficulty":4,"kind":"essay","stem":"9800만에서 1000만씩 세 번 뛰어 센 수들을 쓰고, 자리가 넘어갈 때 어떻게 되는지 설명해 보세요.","answer_guide":{"answer":"예: 9800만 − 1억 800만 − 1억 1800만 − 1억 2800만. 천만의 자리 숫자 9에 1이 더해져 10이 되면 억의 자리로 1을 올리고 천만의 자리는 0이 된다.","scoring_points":["1억 800만을 구했는가","1억 1800만·1억 2800만을 구했는가","천만의 자리가 10이 되면 억의 자리로 올라간다고 설명했는가"]},"explanation":["98000000 + 10000000 = 108000000.","천만의 자리 9 + 1 = 10 → 억의 자리로.","1억 800만, 1억 1800만, 1억 2800만."],"asset":{"type":"number_line","cells":["98000000","108000000","118000000","128000000"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L06_challenge#10','math',4,1,'u1','L06','g4_1_math_u1_L06_challenge','lesson_challenge','M4-1-u1-C8',4,'mc','auto','2억씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M4-1-u1-X10','M4-1-u1-X08']::text[],true,'{"seq":10,"concept":"M4-1-u1-C8","difficulty":4,"kind":"mc","stem":"2억씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"99900000000","correct":true},{"t":"99500000000","mis":"M4-1-u1-X10"},{"t":"101700000000","mis":"M4-1-u1-X08"},{"t":"99720000000","mis":"M4-1-u1-X08"}],"explanation":["2억씩 뛰면 억의 자리 숫자가 2씩 커져요.","99700000000 + 200000000 = 99900000000.","빈칸은 99900000000이에요."],"asset":{"type":"number_line","cells":["99700000000",null,"100100000000","100300000000","100500000000"]},"variant_rule":{"alt":[{"stem":"20000씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"9990000","correct":true},{"t":"9950000","mis":"M4-1-u1-X10"},{"t":"10170000","mis":"M4-1-u1-X08"},{"t":"9972000","mis":"M4-1-u1-X08"}],"explanation":["20000씩 뛰면 만의 자리 숫자가 2씩 커져요.","9970000 + 20000 = 9990000.","빈칸은 9990000이에요."],"asset":{"type":"number_line","cells":["9970000",null,"10010000","10030000","10050000"]}},{"stem":"30만씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"999900000","correct":true},{"t":"999300000","mis":"M4-1-u1-X10"},{"t":"1002600000","mis":"M4-1-u1-X08"},{"t":"999630000","mis":"M4-1-u1-X08"}],"explanation":["30만씩 뛰면 십만의 자리 숫자가 3씩 커져요.","999600000 + 300000 = 999900000.","빈칸은 999900000이에요."],"asset":{"type":"number_line","cells":["999600000",null,"1000200000","1000500000","1000800000"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#1','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C9',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 100000 ○ 99999',ARRAY['M4-1-u1-X13','M4-1-u1-X12','M4-1-u1-X15']::text[],true,'{"seq":1,"concept":"M4-1-u1-C9","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 100000 ○ 99999","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","100000은 6자리, 99999는 5자리 — 자릿수가 많은 쪽이 커요.","100000 > 99999 — 벌어진 쪽이 큰 수예요."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 1000000 ○ 999999","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","1000000은 7자리, 999999는 6자리 — 자릿수가 많은 쪽이 커요.","1000000 > 999999 — 벌어진 쪽이 큰 수예요."],"asset":null},{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 10000000 ○ 9999999","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","10000000은 8자리, 9999999는 7자리 — 자릿수가 많은 쪽이 커요.","10000000 > 9999999 — 벌어진 쪽이 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#2','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C9',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 52780000 ○ 52680000',ARRAY['M4-1-u1-X13','M4-1-u1-X12','M4-1-u1-X15']::text[],true,'{"seq":2,"concept":"M4-1-u1-C9","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 52780000 ○ 52680000","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 7 > 6.","52780000 > 52680000 — 벌어진 쪽이 큰 수예요."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 6721000 ○ 6712000","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 2 > 1.","6721000 > 6712000 — 벌어진 쪽이 큰 수예요."],"asset":null},{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 38450000 ○ 38540000","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 4 < 5.","38450000 < 38540000 — 벌어진 쪽이 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
