INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#4','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C10',1,'mc','auto','수 카드 5, 3, 8, 1, 6을 한 번씩 모두 써서 만들 수 있는 가장 큰 다섯 자리 수는 얼마인가요?',ARRAY['M4-1-u1-X14','M4-1-u1-X15']::text[],true,'{"seq":4,"concept":"M4-1-u1-C10","difficulty":1,"kind":"mc","stem":"수 카드 5, 3, 8, 1, 6을 한 번씩 모두 써서 만들 수 있는 가장 큰 다섯 자리 수는 얼마인가요?","options":[{"t":"86531","correct":true},{"t":"86513","mis":"M4-1-u1-X14"},{"t":"13568","mis":"M4-1-u1-X15"},{"t":"68531","mis":"M4-1-u1-X14"}],"explanation":["높은 자리부터 큰 숫자를 차례로 놓아요.","8 > 6 > 5 > 3 > 1.","가장 큰 수는 86531이에요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 7, 4, 9, 3을 한 번씩 모두 써서 만들 수 있는 가장 큰 다섯 자리 수는 얼마인가요?","options":[{"t":"97432","correct":true},{"t":"97423","mis":"M4-1-u1-X14"},{"t":"23479","mis":"M4-1-u1-X15"},{"t":"79432","mis":"M4-1-u1-X14"}],"explanation":["높은 자리부터 큰 숫자를 차례로 놓아요.","9 > 7 > 4 > 3 > 2.","가장 큰 수는 97432예요."],"asset":null},{"stem":"수 카드 6, 1, 8, 5, 4를 한 번씩 모두 써서 만들 수 있는 가장 큰 다섯 자리 수는 얼마인가요?","options":[{"t":"86541","correct":true},{"t":"86514","mis":"M4-1-u1-X14"},{"t":"14568","mis":"M4-1-u1-X15"},{"t":"68541","mis":"M4-1-u1-X14"}],"explanation":["높은 자리부터 큰 숫자를 차례로 놓아요.","8 > 6 > 5 > 4 > 1.","가장 큰 수는 86541이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#5','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C9',2,'mc','auto','여러 분야의 수출액이에요. 게임 87400000달러, 만화 9200000달러, 영화 15600000달러, 음악 8500000달러 — 수출액이 가장 큰 분야는 어느 것인가요?',ARRAY['M4-1-u1-X11','M4-1-u1-X12','M4-1-u1-X15']::text[],true,'{"seq":5,"concept":"M4-1-u1-C9","difficulty":2,"kind":"mc","stem":"여러 분야의 수출액이에요. 게임 87400000달러, 만화 9200000달러, 영화 15600000달러, 음악 8500000달러 — 수출액이 가장 큰 분야는 어느 것인가요?","options":[{"t":"게임","correct":true},{"t":"만화","mis":"M4-1-u1-X11"},{"t":"영화","mis":"M4-1-u1-X12"},{"t":"음악","mis":"M4-1-u1-X15"}],"explanation":["자릿수를 세어요: 게임 8자리, 만화 7자리, 영화 8자리, 음악 7자리.","자릿수가 같고 천만의 자리에서 8 > 1.","가장 큰 것은 게임이에요."],"variant_rule":{"alt":[{"stem":"여러 분야의 수출액이에요. 자동차 75400000달러, 배 9800000달러, 반도체 128000000달러, 화장품 34600000달러 — 수출액이 가장 큰 분야는 어느 것인가요?","options":[{"t":"반도체","correct":true},{"t":"자동차","mis":"M4-1-u1-X11"},{"t":"배","mis":"M4-1-u1-X11"},{"t":"화장품","mis":"M4-1-u1-X11"}],"explanation":["자릿수를 세어요: 자동차 8자리, 배 7자리, 반도체 9자리, 화장품 8자리.","128000000은 9자리, 75400000은 8자리 — 자릿수가 많은 쪽이 커요.","가장 큰 것은 반도체예요."],"asset":null},{"stem":"여러 분야의 수출액이에요. 라면 4150000달러, 김 8920000달러, 딸기 980000달러, 인삼 12600000달러 — 수출액이 가장 큰 분야는 어느 것인가요?","options":[{"t":"인삼","correct":true},{"t":"라면","mis":"M4-1-u1-X11"},{"t":"김","mis":"M4-1-u1-X11"},{"t":"딸기","mis":"M4-1-u1-X11"}],"explanation":["자릿수를 세어요: 라면 7자리, 김 7자리, 딸기 6자리, 인삼 8자리.","12600000은 8자리, 8920000은 7자리 — 자릿수가 많은 쪽이 커요.","가장 큰 것은 인삼이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#6','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C9',2,'mc','auto','가장 큰 수는 어느 것인가요?',ARRAY['M4-1-u1-X11']::text[],true,'{"seq":6,"concept":"M4-1-u1-C9","difficulty":2,"kind":"mc","stem":"가장 큰 수는 어느 것인가요?","options":[{"t":"1023000","correct":true},{"t":"640200","mis":"M4-1-u1-X11"},{"t":"98760","mis":"M4-1-u1-X11"},{"t":"640020","mis":"M4-1-u1-X11"}],"explanation":["먼저 자릿수를 세어요: 640200(6자리), 1023000(7자리), 98760(5자리), 640020(6자리).","1023000은 7자리, 640200은 6자리 — 자릿수가 많은 쪽이 커요.","가장 큰 수는 1023000이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"3540000","correct":true},{"t":"3504000","mis":"M4-1-u1-X12"},{"t":"984000","mis":"M4-1-u1-X11"},{"t":"3450000","mis":"M4-1-u1-X12"}],"explanation":["먼저 자릿수를 세어요: 3504000(7자리), 984000(6자리), 3540000(7자리), 3450000(7자리).","자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 4 > 0.","가장 큰 수는 3540000이에요."],"asset":null},{"stem":"이번에는 다른 수예요. 가장 큰 수는 어느 것인가요?","options":[{"t":"120000000","correct":true},{"t":"72100000","mis":"M4-1-u1-X11"},{"t":"9870000","mis":"M4-1-u1-X11"},{"t":"72010000","mis":"M4-1-u1-X11"}],"explanation":["먼저 자릿수를 세어요: 72100000(8자리), 9870000(7자리), 72010000(8자리), 120000000(9자리).","120000000은 9자리, 72100000은 8자리 — 자릿수가 많은 쪽이 커요.","가장 큰 수는 120000000이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#7','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C9',2,'ox','auto','99999는 100000보다 커요. 맨 앞 숫자가 더 크니까요.',ARRAY['M4-1-u1-X11']::text[],true,'{"seq":7,"concept":"M4-1-u1-C9","difficulty":2,"kind":"ox","stem":"99999는 100000보다 커요. 맨 앞 숫자가 더 크니까요.","answer":"X","reason_options":[{"t":"자릿수가 많은 100000이 더 커서","correct":true},{"t":"맨 앞 숫자가 큰 수가 더 커서","mis":"M4-1-u1-X11"}],"mis":"M4-1-u1-X11","explanation":["100000은 6자리, 99999는 5자리 — 자릿수가 많은 쪽이 커요.","100000 > 99999.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"6712000은 6721000보다 커요. 일의 자리부터 보면 더 크니까요.","answer":"X","reason_options":[{"t":"높은 자리부터 견주어야 해서","correct":true},{"t":"낮은 자리 숫자가 크면 더 커서","mis":"M4-1-u1-X12"}],"explanation":["자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 2 > 1.","6721000 > 6712000.","그래서 틀렸어요."],"asset":null},{"stem":"5030000은 987000보다 커요.","answer":"O","reason_options":[{"t":"높은 자리부터 견주면 더 커서","correct":true},{"t":"맨 앞 숫자만 보면 작아서","mis":"M4-1-u1-X11"}],"explanation":["5030000은 7자리, 987000은 6자리 — 자릿수가 많은 쪽이 커요.","5030000 > 987000.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
