INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#9','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C10',2,'mc','auto','수 카드 5, 3, 8, 1, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?',ARRAY['M4-1-u1-X14','M4-1-u1-X15']::text[],true,'{"seq":9,"concept":"M4-1-u1-C10","difficulty":2,"kind":"mc","stem":"수 카드 5, 3, 8, 1, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"13568","correct":true},{"t":"13586","mis":"M4-1-u1-X14"},{"t":"86531","mis":"M4-1-u1-X15"},{"t":"31568","mis":"M4-1-u1-X14"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요.","1 < 3 < 5 < 6 < 8.","가장 작은 수는 13568이에요."],"variant_rule":{"alt":[{"stem":"수 카드 4, 9, 2, 7, 5를 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"24579","correct":true},{"t":"24597","mis":"M4-1-u1-X14"},{"t":"97542","mis":"M4-1-u1-X15"},{"t":"42579","mis":"M4-1-u1-X14"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요.","2 < 4 < 5 < 7 < 9.","가장 작은 수는 24579예요."],"asset":null},{"stem":"수 카드 8, 3, 6, 1, 9를 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"13689","correct":true},{"t":"13698","mis":"M4-1-u1-X14"},{"t":"98631","mis":"M4-1-u1-X15"},{"t":"31689","mis":"M4-1-u1-X14"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요.","1 < 3 < 6 < 8 < 9.","가장 작은 수는 13689예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_basic#10','math',4,1,'u1','L07','g4_1_math_u1_L07_basic','lesson_basic','M4-1-u1-C9',3,'error','auto','99999와 100000의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u1-X11','M4-1-u1-X15']::text[],true,'{"seq":10,"concept":"M4-1-u1-C9","difficulty":3,"kind":"error","stem":"99999와 100000의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「99999는 맨 앞 숫자가 커서 더 커」","correct":true,"mis_target":"M4-1-u1-X11"},{"t":"시아 — 「100000 > 99999」","mis":"M4-1-u1-X15"},{"t":"지유 — 「99999는 100000보다 작아」","mis":"M4-1-u1-X15"}],"explanation":["100000은 6자리, 99999는 5자리 — 자릿수가 많은 쪽이 커요.","100000 > 99999.","하린이 잘못 말했어요 — 먼저 자릿수 세기."],"variant_rule":{"alt":[{"stem":"52680000과 52780000의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「52780000 < 52680000」","correct":true,"mis_target":"M4-1-u1-X13"},{"t":"하린 — 「52780000 > 52680000」","mis":"M4-1-u1-X15"},{"t":"도윤 — 「52680000은 52780000보다 작아」","mis":"M4-1-u1-X15"}],"explanation":["자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 7 > 6.","52780000 > 52680000.","은우가 잘못 말했어요 — 벌어진 쪽이 큰 수."],"asset":null},{"stem":"987654와 1023456의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「987654는 맨 앞 숫자가 커서 더 커」","correct":true,"mis_target":"M4-1-u1-X11"},{"t":"은우 — 「1023456 > 987654」","mis":"M4-1-u1-X15"},{"t":"태오 — 「987654는 1023456보다 작아」","mis":"M4-1-u1-X15"}],"explanation":["1023456은 7자리, 987654는 6자리 — 자릿수가 많은 쪽이 커요.","1023456 > 987654.","서준이 잘못 말했어요 — 먼저 자릿수 세기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
