INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#4','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C10',3,'sa','auto','5□718 > 56718에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u1-C10","difficulty":3,"kind":"sa","stem":"5□718 > 56718에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["□는 천의 자리예요 — 56718의 같은 자리 숫자 6과 견주어요.","들어갈 수 있는 숫자: 7, 8, 9. □ = 6이면 두 수가 같아져서 안 돼요.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"38□420 < 385420에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["□는 천의 자리예요 — 385420의 같은 자리 숫자 5와 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4. □ = 5이면 두 수가 같아져서 안 돼요.","모두 5개예요."],"asset":null},{"stem":"7□2600 > 742600에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["□는 만의 자리예요 — 742600의 같은 자리 숫자 4와 견주어요.","들어갈 수 있는 숫자: 5, 6, 7, 8, 9. □ = 4이면 두 수가 같아져서 안 돼요.","모두 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#5','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C10',3,'sa','auto','4□9150 < 469150에서 □ 안에 들어갈 수 있는 가장 큰 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u1-C10","difficulty":3,"kind":"sa","stem":"4□9150 < 469150에서 □ 안에 들어갈 수 있는 가장 큰 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["□는 만의 자리예요 — 469150의 같은 자리 숫자 6과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4, 5. □ = 6이면 두 수가 같아져서 안 돼요.","가장 큰 숫자는 5예요."],"variant_rule":{"alt":[{"stem":"12□7000 < 1257000에서 □ 안에 들어갈 수 있는 가장 큰 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["□는 만의 자리예요 — 1257000의 같은 자리 숫자 5와 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4. □ = 5이면 두 수가 같아져서 안 돼요.","가장 큰 숫자는 4예요."],"asset":null},{"stem":"□6350 < 56350에서 □ 안에 들어갈 수 있는 가장 큰 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["□는 만의 자리예요 — 56350의 같은 자리 숫자 5와 견주어요.","들어갈 수 있는 숫자: 1, 2, 3, 4. □ = 5이면 두 수가 같아져서 안 돼요. 맨 앞에는 0이 올 수 없어요.","가장 큰 숫자는 4예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#6','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C9',3,'mc','auto','1250000, 999000, 1205000 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u1-X15','M4-1-u1-X11','M4-1-u1-X12']::text[],true,'{"seq":6,"concept":"M4-1-u1-C9","difficulty":3,"kind":"mc","stem":"1250000, 999000, 1205000 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1250000 > 1205000 > 999000","correct":true},{"t":"999000 > 1205000 > 1250000","mis":"M4-1-u1-X15"},{"t":"999000 > 1250000 > 1205000","mis":"M4-1-u1-X11"},{"t":"1205000 > 1250000 > 999000","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 7자리, 6자리, 7자리.","자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 5 > 0. 1205000은 7자리, 999000은 6자리 — 자릿수가 많은 쪽이 커요.","1250000 > 1205000 > 999000."],"variant_rule":{"alt":[{"stem":"40800000, 40080000, 9999999 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"40800000 > 40080000 > 9999999","correct":true},{"t":"9999999 > 40080000 > 40800000","mis":"M4-1-u1-X15"},{"t":"9999999 > 40800000 > 40080000","mis":"M4-1-u1-X11"},{"t":"40080000 > 40800000 > 9999999","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 8자리, 8자리, 7자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 8 > 0. 40080000은 8자리, 9999999는 7자리 — 자릿수가 많은 쪽이 커요.","40800000 > 40080000 > 9999999."],"asset":null},{"stem":"300050000, 305000000, 99000000 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"305000000 > 300050000 > 99000000","correct":true},{"t":"99000000 > 300050000 > 305000000","mis":"M4-1-u1-X15"},{"t":"99000000 > 305000000 > 300050000","mis":"M4-1-u1-X11"},{"t":"300050000 > 99000000 > 305000000","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 9자리, 9자리, 8자리.","자릿수가 같고 천만의 자리까지 같아요 — 백만의 자리에서 5 > 0. 300050000은 9자리, 99000000은 8자리 — 자릿수가 많은 쪽이 커요.","305000000 > 300050000 > 99000000."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#7','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C9',3,'mc','auto','두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 10억 6000만 ○ 1600000000',ARRAY['M4-1-u1-X13','M4-1-u1-X12','M4-1-u1-X15']::text[],true,'{"seq":7,"concept":"M4-1-u1-C9","difficulty":3,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 10억 6000만 ○ 1600000000","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["10억 6000만을 수로 쓰면 1060000000이에요.","자릿수가 같고 십억의 자리까지 같아요 — 억의 자리에서 0 < 6.","10억 6000만 < 1600000000 — 벌어진 쪽이 큰 수예요."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 3002만 ○ 3020000","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["3002만을 수로 쓰면 30020000이에요.","30020000은 8자리, 3020000은 7자리 — 자릿수가 많은 쪽이 커요.","3002만 > 3020000 — 벌어진 쪽이 큰 수예요."],"asset":null},{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 5000억 400만 ○ 500040000000","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["5000억 400만을 수로 쓰면 500004000000이에요.","자릿수가 같고 억의 자리까지 같아요 — 천만의 자리에서 0 < 4.","5000억 400만 < 500040000000 — 벌어진 쪽이 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#8','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C9',4,'essay','teacher','게임 수출액은 87400000달러, 영화 수출액은 15600000달러예요. 어느 쪽이 더 큰지 쓰고, 어떻게 비교했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u1-C9","difficulty":4,"kind":"essay","stem":"게임 수출액은 87400000달러, 영화 수출액은 15600000달러예요. 어느 쪽이 더 큰지 쓰고, 어떻게 비교했는지 설명해 보세요.","answer_guide":{"answer":"예: 게임 수출액이 더 크다. 두 수는 모두 여덟 자리로 자릿수가 같으므로 가장 높은 자리인 천만의 자리부터 비교한다. 8 > 1이므로 87400000 > 15600000이다.","scoring_points":["게임 수출액이 더 크다고 답했는가","자릿수가 같음을 확인했는가","천만의 자리 8과 1을 비교해 설명했는가"]},"explanation":["둘 다 8자리.","천만의 자리 8 > 1.","87400000 > 15600000 — 게임."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#9','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C10',4,'essay','teacher','수 카드 0, 4, 7, 2, 9를 한 번씩 모두 써서 가장 큰 다섯 자리 수와 가장 작은 다섯 자리 수를 만들고, 만드는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u1-C10","difficulty":4,"kind":"essay","stem":"수 카드 0, 4, 7, 2, 9를 한 번씩 모두 써서 가장 큰 다섯 자리 수와 가장 작은 다섯 자리 수를 만들고, 만드는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 가장 큰 수는 높은 자리부터 큰 숫자를 놓아 97420, 가장 작은 수는 높은 자리부터 작은 숫자를 놓되 0은 맨 앞에 올 수 없으므로 두 번째로 작은 2를 맨 앞에 놓아 20479이다.","scoring_points":["97420을 만들었는가","20479를 만들었는가","0은 맨 앞에 올 수 없다고 설명했는가"]},"explanation":["큰 수: 9 > 7 > 4 > 2 > 0 → 97420.","작은 수: 0은 맨 앞 불가 → 2를 맨 앞에.","20479."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_L07_challenge#10','math',4,1,'u1','L07','g4_1_math_u1_L07_challenge','lesson_challenge','M4-1-u1-C10',4,'sa','auto','6□4900 > 634900에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u1-C10","difficulty":4,"kind":"sa","stem":"6□4900 > 634900에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["□는 만의 자리예요 — 634900의 같은 자리 숫자 3과 견주어요.","들어갈 수 있는 숫자: 4, 5, 6, 7, 8, 9. □ = 3이면 두 수가 같아져서 안 돼요.","모두 6개예요."],"variant_rule":{"alt":[{"stem":"29□5000 < 2965000에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["□는 만의 자리예요 — 2965000의 같은 자리 숫자 6과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4, 5. □ = 6이면 두 수가 같아져서 안 돼요.","모두 6개예요."],"asset":null},{"stem":"8□07000 > 8507000에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["□는 십만의 자리예요 — 8507000의 같은 자리 숫자 5와 견주어요.","들어갈 수 있는 숫자: 6, 7, 8, 9. □ = 5이면 두 수가 같아져서 안 돼요.","모두 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#1','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C1',1,'mc','auto','1000이 10개인 수는 얼마인가요?',ARRAY['M4-1-u1-X07','M4-1-u1-X16']::text[],true,'{"seq":1,"concept":"M4-1-u1-C1","difficulty":1,"kind":"mc","stem":"1000이 10개인 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"1000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"100","mis":"M4-1-u1-X16"}],"explanation":["1000이 10개인 수는 1000 × 10으로 구해요.","1000 × 10 = 10000 — 0을 4개 써요.","수로 쓰면 10000, 「만」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"100이 100개인 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"1000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"100","mis":"M4-1-u1-X16"}],"explanation":["100이 100개인 수는 100 × 100으로 구해요.","100 × 100 = 10000 — 0을 4개 써요.","수로 쓰면 10000, 「만」이라고 읽어요."],"asset":null},{"stem":"10이 1000개인 수는 얼마인가요?","options":[{"t":"10000","correct":true},{"t":"1000","mis":"M4-1-u1-X07"},{"t":"100000","mis":"M4-1-u1-X07"},{"t":"100","mis":"M4-1-u1-X16"}],"explanation":["10이 1000개인 수는 10 × 1000으로 구해요.","10 × 1000 = 10000 — 0을 4개 써요.","수로 쓰면 10000, 「만」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#2','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C2',1,'mc','auto','10000이 3개, 1000이 9개, 100이 8개, 10이 8개, 1이 4개인 수는 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X18','M4-1-u1-X04']::text[],true,'{"seq":2,"concept":"M4-1-u1-C2","difficulty":1,"kind":"mc","stem":"10000이 3개, 1000이 9개, 100이 8개, 10이 8개, 1이 4개인 수는 얼마인가요?","options":[{"t":"39884","correct":true},{"t":"398840","mis":"M4-1-u1-X16"},{"t":"38984","mis":"M4-1-u1-X18"},{"t":"39880004","mis":"M4-1-u1-X04"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","30000 + 9000 + 800 + 80 + 4 = 39884.","「삼만 구천팔백팔십사」라고 읽어요."],"variant_rule":{"alt":[{"stem":"10000이 7개, 1000이 4개, 100이 5개, 10이 1개, 1이 5개인 수는 얼마인가요?","options":[{"t":"74515","correct":true},{"t":"745150","mis":"M4-1-u1-X16"},{"t":"75415","mis":"M4-1-u1-X18"},{"t":"74155","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","70000 + 4000 + 500 + 10 + 5 = 74515.","「칠만 사천오백십오」라고 읽어요."],"asset":null},{"stem":"10000이 5개, 1000이 5개, 100이 4개, 10이 1개, 1이 7개인 수는 얼마인가요?","options":[{"t":"55417","correct":true},{"t":"554170","mis":"M4-1-u1-X16"},{"t":"54517","mis":"M4-1-u1-X18"},{"t":"55147","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","50000 + 5000 + 400 + 10 + 7 = 55417.","「오만 오천사백십칠」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
