INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#9','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C1',2,'sa','auto','지유는 학용품을 사려고 1000원짜리 지폐 6장, 100원짜리 동전 20개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u1-C1","difficulty":2,"kind":"sa","stem":"지유는 학용품을 사려고 1000원짜리 지폐 6장, 100원짜리 동전 20개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["2000"],"explanation":["가진 돈: 6000원 + 2000원 = 8000원.","10000 − 8000 = 2000.","2000원이 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"지유는 학용품을 사려고 1000원짜리 지폐 8장, 100원짜리 동전 5개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["1500"],"explanation":["가진 돈: 8000원 + 500원 = 8500원.","10000 − 8500 = 1500.","1500원이 더 있어야 해요."],"asset":null},{"stem":"지유는 학용품을 사려고 1000원짜리 지폐 5장, 500원짜리 동전 4개를 모았어요. 10000원이 되려면 얼마가 더 있어야 하나요? 숫자로 쓰세요.","answer":["3000"],"explanation":["가진 돈: 5000원 + 2000원 = 7000원.","10000 − 7000 = 3000.","3000원이 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
