INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#19','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C7',3,'sa','auto','7776896500000000에서 백억의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u1-C7","difficulty":3,"kind":"sa","stem":"7776896500000000에서 백억의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","백억의 자리는 오른쪽에서 11번째 자리예요.","백억의 자리 숫자는 9예요."],"variant_rule":{"alt":[{"stem":"1217260300000000에서 백억의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","백억의 자리는 오른쪽에서 11번째 자리예요.","백억의 자리 숫자는 6이에요."],"asset":null},{"stem":"6337322400000000에서 천조의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천조의 자리는 오른쪽에서 16번째 자리예요.","천조의 자리 숫자는 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
