INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#21','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C9',3,'mc','auto','9990508, 91470402, 91740402 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u1-X15','M4-1-u1-X11','M4-1-u1-X12']::text[],true,'{"seq":21,"concept":"M4-1-u1-C9","difficulty":3,"kind":"mc","stem":"9990508, 91470402, 91740402 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"91740402 > 91470402 > 9990508","correct":true},{"t":"9990508 > 91470402 > 91740402","mis":"M4-1-u1-X15"},{"t":"9990508 > 91740402 > 91470402","mis":"M4-1-u1-X11"},{"t":"91470402 > 91740402 > 9990508","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 7자리, 8자리, 8자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 7 > 4. 91470402는 8자리, 9990508은 7자리 — 자릿수가 많은 쪽이 커요.","91740402 > 91470402 > 9990508."],"variant_rule":{"alt":[{"stem":"992233, 7340055, 7304055 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7340055 > 7304055 > 992233","correct":true},{"t":"992233 > 7304055 > 7340055","mis":"M4-1-u1-X15"},{"t":"992233 > 7340055 > 7304055","mis":"M4-1-u1-X11"},{"t":"7304055 > 7340055 > 992233","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 6자리, 7자리, 7자리.","자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 4 > 0. 7304055는 7자리, 992233은 6자리 — 자릿수가 많은 쪽이 커요.","7340055 > 7304055 > 992233."],"asset":null},{"stem":"50310523, 50130523, 9994186 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"50310523 > 50130523 > 9994186","correct":true},{"t":"9994186 > 50130523 > 50310523","mis":"M4-1-u1-X15"},{"t":"9994186 > 50310523 > 50130523","mis":"M4-1-u1-X11"},{"t":"50130523 > 50310523 > 9994186","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 8자리, 8자리, 7자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 3 > 1. 50130523은 8자리, 9994186은 7자리 — 자릿수가 많은 쪽이 커요.","50310523 > 50130523 > 9994186."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_c