INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#22','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C10',3,'sa','auto','705□2 > 70571에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u1-C10","difficulty":3,"kind":"sa","stem":"705□2 > 70571에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["□는 십의 자리예요 — 70571의 같은 자리 숫자 7과 견주어요.","들어갈 수 있는 숫자: 7, 8, 9. □ = 7이면 아랫자리를 견주어 더 커서 들어갈 수 있어요.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"6□3478 < 684478에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["□는 만의 자리예요 — 684478의 같은 자리 숫자 8과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4, 5, 6, 7, 8. □ = 8이면 아랫자리를 견주어 더 작아서 들어갈 수 있어요.","모두 9개예요."],"asset":null},{"stem":"6□521 > 68421에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["□는 천의 자리예요 — 68421의 같은 자리 숫자 8과 견주어요.","들어갈 수 있는 숫자: 8, 9. □ = 8이면 아랫자리를 견주어 더 커서 들어갈 수 있어요.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#23','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C8',4,'sa','auto','건우는 지금 10000원이 있고, 매달 20000원씩 저금해요. 몇 달 뒤에 모은 돈이 170000원이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u1-C8","difficulty":4,"kind":"sa","stem":"건우는 지금 10000원이 있고, 매달 20000원씩 저금해요. 몇 달 뒤에 모은 돈이 170000원이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["10000에서 20000씩 뛰어 세어요.","10000 − 30000 − 50000 − 70000 − 90000 − 110000 ….","8번 뛰어 세었으니 8달 뒤예요."],"variant_rule":{"alt":[{"stem":"시아는 지금 10000원이 있고, 매달 10000원씩 저금해요. 몇 달 뒤에 모은 돈이 70000원이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["10000에서 10000씩 뛰어 세어요.","10000 − 20000 − 30000 − 40000 − 50000 − 60000 ….","6번 뛰어 세었으니 6달 뒤예요."],"asset":null},{"stem":"하린은 지금 60000원이 있고, 매달 10000원씩 저금해요. 몇 달 뒤에 모은 돈이 120000원이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["60000에서 10000씩 뛰어 세어요.","60000 − 70000 − 80000 − 90000 − 100000 − 110000 ….","6번 뛰어 세었으니 6달 뒤예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#24','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C10',4,'mc','auto','수 카드 0, 3, 5, 9, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?',ARRAY['M4-1-u1-X14','M4-1-u1-X15']::text[],true,'{"seq":24,"concept":"M4-1-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 0, 3, 5, 9, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"30569","correct":true},{"t":"03569","mis":"M4-1-u1-X14"},{"t":"30596","mis":"M4-1-u1-X14"},{"t":"96530","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 3 < 5 < 6 < 9.","가장 작은 수는 30569예요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 0, 3, 2, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10238","correct":true},{"t":"01238","mis":"M4-1-u1-X14"},{"t":"10283","mis":"M4-1-u1-X14"},{"t":"83210","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 2 < 3 < 8.","가장 작은 수는 10238이에요."],"asset":null},{"stem":"수 카드 4, 9, 0, 8, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"40689","correct":true},{"t":"04689","mis":"M4-1-u1-X14"},{"t":"40698","mis":"M4-1-u1-X14"},{"t":"98640","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 4 < 6 < 8 < 9.","가장 작은 수는 40689예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_a#25','math',4,1,'u1','','g4_1_math_u1_review_a','unit_review','M4-1-u1-C5',4,'essay','teacher','광주광역시 인구 「백사십삼만 천오십」 명을 수로 쓰는 방법을 설명하고, 수로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u1-C5","difficulty":4,"kind":"essay","stem":"광주광역시 인구 「백사십삼만 천오십」 명을 수로 쓰는 방법을 설명하고, 수로 써 보세요.","answer_guide":{"answer":"예: 「만」 앞의 백사십삼은 143, 「만」 뒤의 천오십은 네 자리로 1050이다. 앞 묶음 143과 뒤 네 자리 1050을 이어 1431050으로 쓴다.","scoring_points":["만 앞 143을 찾았는가","뒤 네 자리를 1050으로 0을 채워 썼는가","1431050을 썼는가"]},"explanation":["143(만) / 1050(일).","빈 자리는 0으로 채워 네 자리.","1431050."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#1','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C1',1,'sa','auto','10000은 9990보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u1-C1","difficulty":1,"kind":"sa","stem":"10000은 9990보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["9990에서 10000까지 몇이 남았는지 세어요.","9990 + 10 = 10000이에요.","10000은 9990보다 10 더 큰 수예요."],"variant_rule":{"alt":[{"stem":"10000은 9000보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["9000에서 10000까지 몇이 남았는지 세어요.","9000 + 1000 = 10000이에요.","10000은 9000보다 1000 더 큰 수예요."],"asset":null},{"stem":"10000은 9999보다 얼마만큼 더 큰 수인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["9999에서 10000까지 몇이 남았는지 세어요.","9999 + 1 = 10000이에요.","10000은 9999보다 1 더 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#2','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C2',1,'mc','auto','10000이 4개, 1000이 5개, 100이 2개, 10이 7개, 1이 5개인 수는 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X18']::text[],true,'{"seq":2,"concept":"M4-1-u1-C2","difficulty":1,"kind":"mc","stem":"10000이 4개, 1000이 5개, 100이 2개, 10이 7개, 1이 5개인 수는 얼마인가요?","options":[{"t":"45275","correct":true},{"t":"452750","mis":"M4-1-u1-X16"},{"t":"42575","mis":"M4-1-u1-X18"},{"t":"45725","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","40000 + 5000 + 200 + 70 + 5 = 45275.","「사만 오천이백칠십오」라고 읽어요."],"variant_rule":{"alt":[{"stem":"10000이 5개, 1000이 9개, 100이 1개, 10이 1개, 1이 4개인 수는 얼마인가요?","options":[{"t":"59114","correct":true},{"t":"591140","mis":"M4-1-u1-X16"},{"t":"51914","mis":"M4-1-u1-X18"},{"t":"59110004","mis":"M4-1-u1-X04"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","50000 + 9000 + 100 + 10 + 4 = 59114.","「오만 구천백십사」라고 읽어요."],"asset":null},{"stem":"10000이 4개, 1000이 9개, 100이 7개, 10이 5개, 1이 8개인 수는 얼마인가요?","options":[{"t":"49758","correct":true},{"t":"497580","mis":"M4-1-u1-X16"},{"t":"47958","mis":"M4-1-u1-X18"},{"t":"49578","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","40000 + 9000 + 700 + 50 + 8 = 49758.","「사만 구천칠백오십팔」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#3','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C3',1,'sa','auto','52335에서 만의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u1-C3","difficulty":1,"kind":"sa","stem":"52335에서 만의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","만의 자리는 오른쪽에서 5번째 자리예요.","만의 자리 숫자는 5예요."],"variant_rule":{"alt":[{"stem":"71797에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천의 자리는 오른쪽에서 4번째 자리예요.","천의 자리 숫자는 1이에요."],"asset":null},{"stem":"62392에서 천의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천의 자리는 오른쪽에서 4번째 자리예요.","천의 자리 숫자는 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#4','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C4',1,'mc','auto','10000이 100개인 수를 무엇이라고 하나요?',ARRAY['M4-1-u1-X07','M4-1-u1-X16']::text[],true,'{"seq":4,"concept":"M4-1-u1-C4","difficulty":1,"kind":"mc","stem":"10000이 100개인 수를 무엇이라고 하나요?","options":[{"t":"백만","correct":true},{"t":"천만","mis":"M4-1-u1-X07"},{"t":"십만","mis":"M4-1-u1-X07"},{"t":"억","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개 모이면 한 자리 위가 돼요.","10000 × 100 = 1000000.","1000000은 「백만」이에요."],"variant_rule":{"alt":[{"stem":"10000이 1000개인 수를 무엇이라고 하나요?","options":[{"t":"천만","correct":true},{"t":"억","mis":"M4-1-u1-X07"},{"t":"백만","mis":"M4-1-u1-X07"},{"t":"십억","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개 모이면 한 자리 위가 돼요.","10000 × 1000 = 10000000.","10000000은 「천만」이에요."],"asset":null},{"stem":"10000이 10개인 수를 무엇이라고 하나요?","options":[{"t":"십만","correct":true},{"t":"백만","mis":"M4-1-u1-X07"},{"t":"만","mis":"M4-1-u1-X07"},{"t":"천만","mis":"M4-1-u1-X16"}],"explanation":["10000이 10개 모이면 한 자리 위가 돼요.","10000 × 10 = 100000.","100000은 「십만」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
