INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#8','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C9',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 27006149 ○ 27006349',ARRAY['M4-1-u1-X13','M4-1-u1-X12','M4-1-u1-X15']::text[],true,'{"seq":8,"concept":"M4-1-u1-C9","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 27006149 ○ 27006349","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","자릿수가 같고 천의 자리까지 같아요 — 백의 자리에서 1 < 3.","27006149 < 27006349 — 벌어진 쪽이 큰 수예요."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 4604550 ○ 4609550","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","자릿수가 같고 만의 자리까지 같아요 — 천의 자리에서 4 < 9.","4604550 < 4609550 — 벌어진 쪽이 큰 수예요."],"asset":null},{"stem":"두 수의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 42860232 ○ 42862232","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u1-X13"},{"t":"=","mis":"M4-1-u1-X12"},{"t":"알 수 없다","mis":"M4-1-u1-X15"}],"explanation":["두 수의 자릿수부터 세어요.","자릿수가 같고 만의 자리까지 같아요 — 천의 자리에서 0 < 2.","42860232 < 42862232 — 벌어진 쪽이 큰 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#9','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C1',2,'sa','auto','10000원짜리 지폐 1장을 1000원짜리 지폐 6장과 100원짜리 동전 몇 개로 바꾸려고 해요. 100원짜리 동전은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u1-C1","difficulty":2,"kind":"sa","stem":"10000원짜리 지폐 1장을 1000원짜리 지폐 6장과 100원짜리 동전 몇 개로 바꾸려고 해요. 100원짜리 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["1000원짜리 6장은 6000원.","10000 − 6000 = 4000원이 남아요.","4000원 = 100원 × 40 — 40개예요."],"variant_rule":{"alt":[{"stem":"10000원짜리 지폐 1장을 1000원짜리 지폐 8장과 500원짜리 동전 몇 개로 바꾸려고 해요. 500원짜리 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1000원짜리 8장은 8000원.","10000 − 8000 = 2000원이 남아요.","2000원 = 500원 × 4 — 4개예요."],"asset":null},{"stem":"10000원짜리 지폐 1장을 1000원짜리 지폐 3장과 100원짜리 동전 몇 개로 바꾸려고 해요. 100원짜리 동전은 몇 개인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["1000원짜리 3장은 3000원.","10000 − 3000 = 7000원이 남아요.","7000원 = 100원 × 70 — 70개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
