INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#22','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C10',3,'sa','auto','95261□5 < 9526134에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u1-C10","difficulty":3,"kind":"sa","stem":"95261□5 < 9526134에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["□는 십의 자리예요 — 9526134의 같은 자리 숫자 3과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2. □ = 3이면 아랫자리를 견주어 보니 들어갈 수 없어요.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"85□240 > 856340에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["□는 천의 자리예요 — 856340의 같은 자리 숫자 6과 견주어요.","들어갈 수 있는 숫자: 7, 8, 9. □ = 6이면 아랫자리를 견주어 보니 들어갈 수 없어요.","모두 3개예요."],"asset":null},{"stem":"3095□85 < 3095895에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["□는 백의 자리예요 — 3095895의 같은 자리 숫자 8과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4, 5, 6, 7, 8. □ = 8이면 아랫자리를 견주어 더 작아서 들어갈 수 있어요.","모두 9개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#23','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C8',4,'mc','auto','70750000000에서 1억씩 3번 뛰어 센 수는 얼마인가요?',ARRAY['M4-1-u1-X18','M4-1-u1-X08']::text[],true,'{"seq":23,"concept":"M4-1-u1-C8","difficulty":4,"kind":"mc","stem":"70750000000에서 1억씩 3번 뛰어 센 수는 얼마인가요?","options":[{"t":"71050000000","correct":true},{"t":"70950000000","mis":"M4-1-u1-X18"},{"t":"71150000000","mis":"M4-1-u1-X18"},{"t":"73750000000","mis":"M4-1-u1-X08"}],"explanation":["1억씩 3번이면 모두 3억만큼 커져요.","70750000000 + 300000000 = 71050000000.","답은 71050000000이에요."],"variant_rule":{"alt":[{"stem":"44900000에서 10만씩 4번 뛰어 센 수는 얼마인가요?","options":[{"t":"45300000","correct":true},{"t":"45200000","mis":"M4-1-u1-X18"},{"t":"45400000","mis":"M4-1-u1-X18"},{"t":"48900000","mis":"M4-1-u1-X08"}],"explanation":["10만씩 4번이면 모두 40만만큼 커져요.","44900000 + 400000 = 45300000.","답은 45300000이에요."],"asset":null},{"stem":"603300000에서 100만씩 7번 뛰어 센 수는 얼마인가요?","options":[{"t":"610300000","correct":true},{"t":"609300000","mis":"M4-1-u1-X18"},{"t":"611300000","mis":"M4-1-u1-X18"},{"t":"673300000","mis":"M4-1-u1-X08"}],"explanation":["100만씩 7번이면 모두 700만만큼 커져요.","603300000 + 7000000 = 610300000.","답은 610300000이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#24','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C10',4,'mc','auto','수 카드 1, 5, 6, 8, 0을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?',ARRAY['M4-1-u1-X14','M4-1-u1-X15']::text[],true,'{"seq":24,"concept":"M4-1-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 1, 5, 6, 8, 0을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10568","correct":true},{"t":"01568","mis":"M4-1-u1-X14"},{"t":"10586","mis":"M4-1-u1-X14"},{"t":"86510","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 5 < 6 < 8.","가장 작은 수는 10568이에요."],"variant_rule":{"alt":[{"stem":"수 카드 8, 4, 0, 7, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"40678","correct":true},{"t":"04678","mis":"M4-1-u1-X14"},{"t":"40687","mis":"M4-1-u1-X14"},{"t":"87640","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 4 < 6 < 7 < 8.","가장 작은 수는 40678이에요."],"asset":null},{"stem":"수 카드 0, 1, 7, 2, 3을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10237","correct":true},{"t":"01237","mis":"M4-1-u1-X14"},{"t":"10273","mis":"M4-1-u1-X14"},{"t":"73210","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 2 < 3 < 7.","가장 작은 수는 10237이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_b#25','math',4,1,'u1','','g4_1_math_u1_review_b','unit_review','M4-1-u1-C8',4,'essay','teacher','1억 6000만에서 2000만씩 세 번 뛰어 센 수들을 쓰고, 어느 자리 숫자가 어떻게 바뀌는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u1-C8","difficulty":4,"kind":"essay","stem":"1억 6000만에서 2000만씩 세 번 뛰어 센 수들을 쓰고, 어느 자리 숫자가 어떻게 바뀌는지 설명해 보세요.","answer_guide":{"answer":"예: 1억 8000만 − 2억 − 2억 2000만. 2000만씩 뛰면 천만의 자리 숫자가 2씩 커지고, 8에서 2가 커져 10이 되면 억의 자리로 1을 올린다.","scoring_points":["1억 8000만·2억·2억 2000만을 구했는가","천만의 자리가 2씩 커진다고 했는가","억의 자리로 올라가는 것을 설명했는가"]},"explanation":["160000000 + 20000000 = 180000000.","천만의 자리 8 + 2 = 10 → 억의 자리로.","1억 8000만, 2억, 2억 2000만."],"asset":{"type":"number_line","cells":["160000000","180000000","200000000","220000000"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#1','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C1',1,'sa','auto','1000원짜리 지폐만 모아 10000원을 만들려고 해요. 1000원짜리 지폐가 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u1-C1","difficulty":1,"kind":"sa","stem":"1000원짜리 지폐만 모아 10000원을 만들려고 해요. 1000원짜리 지폐가 몇 장 필요한가요? 숫자로 쓰세요.","answer":["10"],"explanation":["10000원은 1000원이 몇 장인지 생각해요.","1000원 × 10 = 10000원.","1000원짜리 지폐 10장이 필요해요."],"variant_rule":{"alt":[{"stem":"100원짜리 동전만 모아 10000원을 만들려고 해요. 100원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["100"],"explanation":["10000원은 100원이 몇 개인지 생각해요.","100원 × 100 = 10000원.","100원짜리 동전 100개가 필요해요."],"asset":null},{"stem":"500원짜리 동전만 모아 10000원을 만들려고 해요. 500원짜리 동전이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["20"],"explanation":["10000원은 500원이 몇 개인지 생각해요.","500원 × 20 = 10000원.","500원짜리 동전 20개가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#2','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C2',1,'mc','auto','10000이 2개, 1000이 3개, 100이 8개, 10이 8개, 1이 8개인 수는 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X18','M4-1-u1-X04']::text[],true,'{"seq":2,"concept":"M4-1-u1-C2","difficulty":1,"kind":"mc","stem":"10000이 2개, 1000이 3개, 100이 8개, 10이 8개, 1이 8개인 수는 얼마인가요?","options":[{"t":"23888","correct":true},{"t":"238880","mis":"M4-1-u1-X16"},{"t":"28388","mis":"M4-1-u1-X18"},{"t":"23880008","mis":"M4-1-u1-X04"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","20000 + 3000 + 800 + 80 + 8 = 23888.","「이만 삼천팔백팔십팔」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"10000이 5개, 1000이 2개, 100이 6개, 10이 4개, 1이 3개인 수는 얼마인가요?","options":[{"t":"52643","correct":true},{"t":"526430","mis":"M4-1-u1-X16"},{"t":"56243","mis":"M4-1-u1-X18"},{"t":"52463","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","50000 + 2000 + 600 + 40 + 3 = 52643.","「오만 이천육백사십삼」이라고 읽어요."],"asset":null},{"stem":"10000이 7개, 1000이 2개, 100이 9개, 10이 8개, 1이 4개인 수는 얼마인가요?","options":[{"t":"72984","correct":true},{"t":"729840","mis":"M4-1-u1-X16"},{"t":"79284","mis":"M4-1-u1-X18"},{"t":"72894","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","70000 + 2000 + 900 + 80 + 4 = 72984.","「칠만 이천구백팔십사」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
