INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#20','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C8',3,'mc','auto','100만씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M4-1-u1-X09','M4-1-u1-X10','M4-1-u1-X08']::text[],true,'{"seq":20,"concept":"M4-1-u1-C8","difficulty":3,"kind":"mc","stem":"100만씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"770300000","correct":true},{"t":"760300000","mis":"M4-1-u1-X09"},{"t":"768300000","mis":"M4-1-u1-X10"},{"t":"779300000","mis":"M4-1-u1-X08"}],"explanation":["100만씩 뛰면 백만의 자리 숫자가 1씩 커져요.","769300000 + 1000000 = 770300000.","9보다 커지면 윗자리로 올라가요."],"asset":{"type":"number_line","cells":["766300000","767300000","768300000","769300000",null]},"variant_rule":{"alt":[{"stem":"200만씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"280700000","correct":true},{"t":"270700000","mis":"M4-1-u1-X09"},{"t":"276700000","mis":"M4-1-u1-X10"},{"t":"298700000","mis":"M4-1-u1-X08"}],"explanation":["200만씩 뛰면 백만의 자리 숫자가 2씩 커져요.","278700000 + 2000000 = 280700000.","9보다 커지면 윗자리로 올라가요."],"asset":{"type":"number_line","cells":["272700000","274700000","276700000","278700000",null]}},{"stem":"30000씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"2931000","correct":true},{"t":"2871000","mis":"M4-1-u1-X10"},{"t":"3201000","mis":"M4-1-u1-X08"},{"t":"2904000","mis":"M4-1-u1-X08"}],"explanation":["30000씩 뛰면 만의 자리 숫자가 3씩 커져요.","2901000 + 30000 = 2931000.","빈칸은 2931000이에요."],"asset":{"type":"number_line","cells":["2811000","2841000","2871000","2901000",null]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#21','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C9',3,'mc','auto','9998745, 89608209, 89068209 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u1-X15','M4-1-u1-X11','M4-1-u1-X12']::text[],true,'{"seq":21,"concept":"M4-1-u1-C9","difficulty":3,"kind":"mc","stem":"9998745, 89608209, 89068209 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"89608209 > 89068209 > 9998745","correct":true},{"t":"9998745 > 89068209 > 89608209","mis":"M4-1-u1-X15"},{"t":"9998745 > 89608209 > 89068209","mis":"M4-1-u1-X11"},{"t":"89068209 > 89608209 > 9998745","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 7자리, 8자리, 8자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 6 > 0. 89068209는 8자리, 9998745는 7자리 — 자릿수가 많은 쪽이 커요.","89608209 > 89068209 > 9998745."],"variant_rule":{"alt":[{"stem":"994063, 6350092, 6305092 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6350092 > 6305092 > 994063","correct":true},{"t":"994063 > 6305092 > 6350092","mis":"M4-1-u1-X15"},{"t":"994063 > 6350092 > 6305092","mis":"M4-1-u1-X11"},{"t":"6305092 > 6350092 > 994063","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 6자리, 7자리, 7자리.","자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 5 > 0. 6305092는 7자리, 994063은 6자리 — 자릿수가 많은 쪽이 커요.","6350092 > 6305092 > 994063."],"asset":null},{"stem":"70865250, 9999555, 70685250 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"70865250 > 70685250 > 9999555","correct":true},{"t":"9999555 > 70685250 > 70865250","mis":"M4-1-u1-X15"},{"t":"9999555 > 70865250 > 70685250","mis":"M4-1-u1-X11"},{"t":"70685250 > 70865250 > 9999555","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 8자리, 7자리, 8자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 8 > 6. 70685250은 8자리, 9999555는 7자리 — 자릿수가 많은 쪽이 커요.","70865250 > 70685250 > 9999555."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#22','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C10',3,'sa','auto','21477□1 < 2147760에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u1-C10","difficulty":3,"kind":"sa","stem":"21477□1 < 2147760에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["□는 십의 자리예요 — 2147760의 같은 자리 숫자 6과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4, 5. □ = 6이면 아랫자리를 견주어 보니 들어갈 수 없어요.","모두 6개예요."],"variant_rule":{"alt":[{"stem":"5□5372 < 546372에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["□는 만의 자리예요 — 546372의 같은 자리 숫자 4와 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3, 4. □ = 4이면 아랫자리를 견주어 더 작아서 들어갈 수 있어요.","모두 5개예요."],"asset":null},{"stem":"80□55 > 80145에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["□는 백의 자리예요 — 80145의 같은 자리 숫자 1과 견주어요.","들어갈 수 있는 숫자: 1, 2, 3, 4, 5, 6, 7, 8, 9. □ = 1이면 아랫자리를 견주어 더 커서 들어갈 수 있어요.","모두 9개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#23','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C8',4,'sa','auto','건우는 지금 40000원이 있고, 매달 25000원씩 저금해요. 몇 달 뒤에 모은 돈이 165000원이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u1-C8","difficulty":4,"kind":"sa","stem":"건우는 지금 40000원이 있고, 매달 25000원씩 저금해요. 몇 달 뒤에 모은 돈이 165000원이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["40000에서 25000씩 뛰어 세어요.","40000 − 65000 − 90000 − 115000 − 140000 − 165000.","5번 뛰어 세었으니 5달 뒤예요."],"variant_rule":{"alt":[{"stem":"도윤은 지금 10000원이 있고, 매달 20000원씩 저금해요. 몇 달 뒤에 모은 돈이 90000원이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["10000에서 20000씩 뛰어 세어요.","10000 − 30000 − 50000 − 70000 − 90000.","4번 뛰어 세었으니 4달 뒤예요."],"asset":null},{"stem":"시아는 지금 10000원이 있고, 매달 20000원씩 저금해요. 몇 달 뒤에 모은 돈이 190000원이 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["10000에서 20000씩 뛰어 세어요.","10000 − 30000 − 50000 − 70000 − 90000 − 110000 ….","9번 뛰어 세었으니 9달 뒤예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#24','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C10',4,'mc','auto','수 카드 9, 5, 0, 1, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?',ARRAY['M4-1-u1-X14','M4-1-u1-X15']::text[],true,'{"seq":24,"concept":"M4-1-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 9, 5, 0, 1, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10589","correct":true},{"t":"01589","mis":"M4-1-u1-X14"},{"t":"10598","mis":"M4-1-u1-X14"},{"t":"98510","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 5 < 8 < 9.","가장 작은 수는 10589예요."],"variant_rule":{"alt":[{"stem":"수 카드 0, 5, 2, 3, 7을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"20357","correct":true},{"t":"02357","mis":"M4-1-u1-X14"},{"t":"20375","mis":"M4-1-u1-X14"},{"t":"75320","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 2 < 3 < 5 < 7.","가장 작은 수는 20357이에요."],"asset":null},{"stem":"수 카드 2, 3, 8, 0, 7을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"20378","correct":true},{"t":"02378","mis":"M4-1-u1-X14"},{"t":"20387","mis":"M4-1-u1-X14"},{"t":"87320","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 2 < 3 < 7 < 8.","가장 작은 수는 20378이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_c#25','math',4,1,'u1','','g4_1_math_u1_review_c','unit_review','M4-1-u1-C9',4,'essay','teacher','두 나라의 인구가 「5174만 명」과 「6850만 명」이에요. 부등호를 써서 비교하고, 비교한 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u1-C9","difficulty":4,"kind":"essay","stem":"두 나라의 인구가 「5174만 명」과 「6850만 명」이에요. 부등호를 써서 비교하고, 비교한 방법을 설명해 보세요.","answer_guide":{"answer":"예: 51740000 < 68500000. 두 수 모두 여덟 자리이므로 가장 높은 천만의 자리부터 비교한다. 5 < 6이므로 5174만이 더 작다.","scoring_points":["51740000 < 68500000으로 나타냈는가","자릿수가 같음을 확인했는가","천만의 자리 5와 6을 비교했는가"]},"explanation":["둘 다 8자리.","천만의 자리 5 < 6.","5174만 < 6850만."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#1','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C1',1,'sa','auto','10000은 1000의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u1-C1","difficulty":1,"kind":"sa","stem":"10000은 1000의 몇 배인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["1000이 10개 모이면 10000이에요.","1000 × 10 = 10000.","10배예요."],"variant_rule":{"alt":[{"stem":"10000은 100의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["100이 100개 모이면 10000이에요.","100 × 100 = 10000.","100배예요."],"asset":null},{"stem":"10000은 10의 몇 배인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["10이 1000개 모이면 10000이에요.","10 × 1000 = 10000.","1000배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#2','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C2',1,'mc','auto','10000이 6개, 1000이 9개, 100이 7개, 10이 5개, 1이 9개인 수는 얼마인가요?',ARRAY['M4-1-u1-X16','M4-1-u1-X18']::text[],true,'{"seq":2,"concept":"M4-1-u1-C2","difficulty":1,"kind":"mc","stem":"10000이 6개, 1000이 9개, 100이 7개, 10이 5개, 1이 9개인 수는 얼마인가요?","options":[{"t":"69759","correct":true},{"t":"697590","mis":"M4-1-u1-X16"},{"t":"67959","mis":"M4-1-u1-X18"},{"t":"69579","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","60000 + 9000 + 700 + 50 + 9 = 69759.","「육만 구천칠백오십구」라고 읽어요."],"variant_rule":{"alt":[{"stem":"10000이 9개, 1000이 7개, 100이 8개, 10이 7개, 1이 1개인 수는 얼마인가요?","options":[{"t":"97871","correct":true},{"t":"978710","mis":"M4-1-u1-X16"},{"t":"98771","mis":"M4-1-u1-X18"},{"t":"97781","mis":"M4-1-u1-X18"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","90000 + 7000 + 800 + 70 + 1 = 97871.","「구만 칠천팔백칠십일」이라고 읽어요."],"asset":null},{"stem":"10000이 6개, 1000이 6개, 100이 7개, 10이 7개, 1이 2개인 수는 얼마인가요?","options":[{"t":"66772","correct":true},{"t":"667720","mis":"M4-1-u1-X16"},{"t":"67672","mis":"M4-1-u1-X18"},{"t":"66770002","mis":"M4-1-u1-X04"}],"explanation":["만·천·백·십·일 칸에 개수를 차례로 써요.","60000 + 6000 + 700 + 70 + 2 = 66772.","「육만 육천칠백칠십이」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
