INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#19','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C7',3,'sa','auto','4527803400000000에서 천억의 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u1-C7","difficulty":3,"kind":"sa","stem":"4527803400000000에서 천억의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천억의 자리는 오른쪽에서 12번째 자리예요.","천억의 자리 숫자는 8이에요."],"variant_rule":{"alt":[{"stem":"9525112000000000에서 천억의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천억의 자리는 오른쪽에서 12번째 자리예요.","천억의 자리 숫자는 1이에요."],"asset":null},{"stem":"2521304500000000에서 천조의 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리부터 일·십·백·천, 만·십만·백만·천만, 억… 차례로 세어요.","천조의 자리는 오른쪽에서 16번째 자리예요.","천조의 자리 숫자는 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
