INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#21','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C9',3,'mc','auto','43086610, 43806610, 9993263 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u1-X15','M4-1-u1-X11','M4-1-u1-X12']::text[],true,'{"seq":21,"concept":"M4-1-u1-C9","difficulty":3,"kind":"mc","stem":"43086610, 43806610, 9993263 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"43806610 > 43086610 > 9993263","correct":true},{"t":"9993263 > 43086610 > 43806610","mis":"M4-1-u1-X15"},{"t":"9993263 > 43806610 > 43086610","mis":"M4-1-u1-X11"},{"t":"43086610 > 43806610 > 9993263","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 8자리, 8자리, 7자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 8 > 0. 43086610은 8자리, 9993263은 7자리 — 자릿수가 많은 쪽이 커요.","43806610 > 43086610 > 9993263."],"variant_rule":{"alt":[{"stem":"9999832, 39075820, 39705820 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"39705820 > 39075820 > 9999832","correct":true},{"t":"9999832 > 39075820 > 39705820","mis":"M4-1-u1-X15"},{"t":"9999832 > 39705820 > 39075820","mis":"M4-1-u1-X11"},{"t":"39075820 > 39705820 > 9999832","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 7자리, 8자리, 8자리.","자릿수가 같고 백만의 자리까지 같아요 — 십만의 자리에서 7 > 0. 39075820은 8자리, 9999832는 7자리 — 자릿수가 많은 쪽이 커요.","39705820 > 39075820 > 9999832."],"asset":null},{"stem":"993185, 6060912, 6006912 큰 수부터 차례로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6060912 > 6006912 > 993185","correct":true},{"t":"993185 > 6006912 > 6060912","mis":"M4-1-u1-X15"},{"t":"993185 > 6060912 > 6006912","mis":"M4-1-u1-X11"},{"t":"6006912 > 6060912 > 993185","mis":"M4-1-u1-X12"}],"explanation":["자릿수를 세어요: 6자리, 7자리, 7자리.","자릿수가 같고 십만의 자리까지 같아요 — 만의 자리에서 6 > 0. 6006912는 7자리, 993185는 6자리 — 자릿수가 많은 쪽이 커요.","6060912 > 6006912 > 993185."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#22','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C10',3,'sa','auto','6711□4 < 671135에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u1-C10","difficulty":3,"kind":"sa","stem":"6711□4 < 671135에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["□는 십의 자리예요 — 671135의 같은 자리 숫자 3과 견주어요.","들어갈 수 있는 숫자: 0, 1, 2, 3. □ = 3이면 아랫자리를 견주어 더 작아서 들어갈 수 있어요.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"544□67 > 544677에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["□는 백의 자리예요 — 544677의 같은 자리 숫자 6과 견주어요.","들어갈 수 있는 숫자: 7, 8, 9. □ = 6이면 아랫자리를 견주어 보니 들어갈 수 없어요.","모두 3개예요."],"asset":null},{"stem":"406□19 > 406729에서 0부터 9까지의 숫자 가운데 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["□는 백의 자리예요 — 406729의 같은 자리 숫자 7과 견주어요.","들어갈 수 있는 숫자: 8, 9. □ = 7이면 아랫자리를 견주어 보니 들어갈 수 없어요.","모두 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
