INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#24','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C10',4,'mc','auto','수 카드 2, 4, 9, 0, 1을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?',ARRAY['M4-1-u1-X14','M4-1-u1-X15']::text[],true,'{"seq":24,"concept":"M4-1-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 2, 4, 9, 0, 1을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10249","correct":true},{"t":"01249","mis":"M4-1-u1-X14"},{"t":"10294","mis":"M4-1-u1-X14"},{"t":"94210","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 2 < 4 < 9.","가장 작은 수는 10249예요."],"variant_rule":{"alt":[{"stem":"수 카드 9, 1, 0, 7, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10789","correct":true},{"t":"01789","mis":"M4-1-u1-X14"},{"t":"10798","mis":"M4-1-u1-X14"},{"t":"98710","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 7 < 8 < 9.","가장 작은 수는 10789예요."],"asset":null},{"stem":"수 카드 1, 8, 0, 9, 2를 한 번씩 모두 써서 만들 수 있는 가장 작은 다섯 자리 수는 얼마인가요?","options":[{"t":"10289","correct":true},{"t":"01289","mis":"M4-1-u1-X14"},{"t":"10298","mis":"M4-1-u1-X14"},{"t":"98210","mis":"M4-1-u1-X15"}],"explanation":["높은 자리부터 작은 숫자를 차례로 놓아요. 0은 맨 앞에 올 수 없어요.","0 < 1 < 2 < 8 < 9.","가장 작은 수는 10289예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u1_review_d#25','math',4,1,'u1','','g4_1_math_u1_review_d','unit_review','M4-1-u1-C7',4,'essay','teacher','「칠천삼백구십이조」를 수로 쓰면 몇 자리 수인지 쓰고, 천조의 자리 숫자를 찾는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u1-C7","difficulty":4,"kind":"essay","stem":"「칠천삼백구십이조」를 수로 쓰면 몇 자리 수인지 쓰고, 천조의 자리 숫자를 찾는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 7392000000000000로 16자리이다. 일의 자리부터 네 자리씩 끊으면 7392 / 0000 / 0000 / 0000이고, 조 묶음 7392의 맨 앞 7이 천조의 자리 숫자이다.","scoring_points":["16자리라고 답했는가","네 자리씩 끊어 조 묶음을 찾았는가","천조의 자리 숫자 7을 찾았는가"]},"explanation":["7392 / 0000 / 0000 / 0000.","조 묶음 7392 — 천조·백조·십조·조.","천조의 자리 숫자 7."],"asset":{"type":"expr_grid","rows":[["조","억","만","일"],["7392","0000","0000","0000"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
